							actionLua = "local now = Now()\nlocal last = data.matthewChainbladeSwap\nif last and now - last < 1000 then self.used = true; return end\nlocal S = data.ark and data.ark.m_chainblade\nif S and now - S.t < 14000 then S.hit1 = S.hit1 or now end\nlocal id = eventArgs.spellID\nlocal preview = data.matthewMirroredCleave\nif not (preview and preview.id == id and preview.caster == eventArgs.entityID and now < preview.expires) then\n    local caster = TensorCore.mGetEntity(eventArgs.entityID)\n    local pos = caster and caster.pos\n    if pos then\n        local offset = (id == 43891 or id == 45085) and -7 or 7\n        preview = {x=pos.x+offset*math.cos(pos.h), y=pos.y,\n            z=pos.z-offset*math.sin(pos.h), heading=pos.h}\n    else\n        preview = nil\n    end\nend\ndata.matthewMirroredCleave = nil\nlocal beams = data.matthewChainbladeBeams\nif preview and beams and not beams.revealed and now-beams.started < 10000 then\n    beams.revealed=true\n    local fx,fz=math.sin(preview.heading),math.cos(preview.heading)\n    local side=(id==43891 or id==45085) and -1 or 1\n    local bx,bz=preview.x-side*7*fz,preview.z+side*7*fx\n    local drawer=TensorCore.getCachedDrawer(0x372222FF,0x372222FF,0x372222FF,0xFF2222FF,4)\n    for repeatId, beam in pairs(beams.first) do\n        local lateral=(beam.x-bx)*fz-(beam.z-bz)*fx\n        local h=2*preview.heading-beam.h\n        local late=repeatId==43896 or repeatId==45080 or repeatId==45092 or repeatId==45095\n        beams.predicted[repeatId]=drawer:addTimedRect(late and 3500 or 3100,\n            beam.x-2*lateral*fz,beam.y,beam.z+2*lateral*fx,40,4,h,0,false,true)\n    end\nend\nif preview then\n    local previous = data.matthewNextSide\n    if previous then Argus.deleteTimedShape(previous) end\n    data.matthewNextSide = TensorCore.getCachedDrawer(0x412222FF,0x412222FF,0x412222FF,0xFF2222FF,5)\n        :addTimedCenteredRect(4200,preview.x,preview.y,preview.z,80,28,preview.heading,0,false,true)\nend\nif AnyoneCore and AnyoneCore.Shotcall then\n    data.matthewChainbladeSwap = now\n    local leftSafe = id == 43891 or id == 45085\n    AnyoneCore.Shotcall(leftSafe and \"Boss left safe\" or \"Boss right safe\", true, 2)\nend\nself.used = true",
