							aType = "Lua",
							actionLua = "data.ark = data.ark or {}\nlocal A = data.ark\nif A.initV ~= 3 then\n  A.initV = 3\n  A.flags = Argus2.RenderFlags.FLAG_RENDER_OVERLAY\n  A.CX, A.CZ = 100, 100\n  -- same arrow as the Zelenia draws: line + arrow from you to the spot, circle on the spot\n  function A.goTo(x, z, col, rad)\n    local p = TensorCore.mGetPlayer()\n    if not (p and p.pos) then return end\n    local g = TensorCore.getCachedDrawer(0x55000000 + col, 0x88000000 + col, 0xFF000000 + col, 0xFF000000, 2)\n    local px, py, pz = p.pos.x, p.pos.y, p.pos.z\n    local d = TensorCore.getDistance2d2(px, py, pz, x, py, z)\n    if d > 0.8 then\n      TensorCore.getStaticDrawer(0xFF000000 + col, 3):addLine(px, py, pz, x, py, z, 3)\n      local tip = math.min(1.5, d * 0.35)\n      g:addArrow(px, py, pz, TensorCore.getHeadingToTarget2(px, py, pz, x, py, z), math.max(0.1, d - tip), 0.65, tip, 1.3, false, A.flags)\n    end\n    g:addCircle(x, py, z, rad or 1.0, false, A.flags)\n  end\n  -- outline ring (your own tower)\n  function A.ring(x, z, r, col)\n    local p = TensorCore.mGetPlayer()\n    local py = p and p.pos and p.pos.y or 0\n    TensorCore.getCachedDrawer(0x22000000 + col, 0x33000000 + col, 0x55000000 + col, 0xFF000000 + col, 3):addCircle(x, py, z, r, false, A.flags)\n  end\n  -- towers: 4 small (43920, r2, one per quadrant) + 2 big (43921, r4, one in the NW half, one in the SE half)\n  A.TOWER_KEYS  = {\"AUTO\", \"BIG_NW\", \"BIG_SE\", \"SM_NW\", \"SM_NE\", \"SM_SE\", \"SM_SW\", \"NONE\"}\n  -- names: tower, who takes it (role slots) and the closest waymark (A N, B E, C S, D W, 1 NW, 2 NE, 3 SE, 4 SW)\n  A.TOWER_NAMES = {\"Auto (Party Roster slot)\",\n                   \"Big tower NW - MT (between D and 1)\", \"Big tower SE - OT (between B and 3)\",\n                   \"Small tower NW - R1 (by 1)\", \"Small tower NE - R2 / H2 (by 2)\",\n                   \"Small tower SE - M2 (by 3)\", \"Small tower SW - M1 / H1 (by 4)\", \"No tower (flex)\"}\n  A.TDIR = {BIG_NW = {-1, -1, true}, BIG_SE = {1, 1, true}, SM_NW = {-1, -1, false}, SM_NE = {1, -1, false},\n            SM_SE = {1, 1, false}, SM_SW = {-1, 1, false}}\n  -- strat defaults: tanks NW/SE, R1 by 1 (NW), R2 by 2 (NE), M1 by 4 (SW), M2 by 3 (SE), H1 west -> SW, H2 east -> NE\n  A.SLOT_TOWER = {T1 = \"BIG_NW\", T2 = \"BIG_SE\", R1 = \"SM_NW\", R2 = \"SM_NE\", M1 = \"SM_SW\", M2 = \"SM_SE\", H1 = \"SM_SW\", H2 = \"SM_NE\"}\n  -- settings saved with FileSave / FileLoad in TensorReactions\\Settings\\Arkveld.settings.lua\n  -- (the old TensorReactions\\ArkveldEX_settings.lua is still read if the new file isn't there yet)\n  A.CFG_DIR = GetLuaModsPath() .. [[TensorReactions\\Settings\\]]\n  A.CFG_PATH = A.CFG_DIR .. [[Arkveld.settings.lua]]\n  local oldPath = GetLuaModsPath() .. [[TensorReactions\\ArkveldEX_settings.lua]]\n  local cfg = {tower = \"AUTO\", lcArrows = true, towerArrows = true, countdown = true}\n  local src = (FileExists(A.CFG_PATH) and A.CFG_PATH) or (FileExists(oldPath) and oldPath) or nil\n  if src then\n    local ok, saved = pcall(FileLoad, src)\n    if ok and type(saved) == \"table\" then\n      for k, v in pairs(saved) do\n        if cfg[k] ~= nil and type(v) == type(cfg[k]) then cfg[k] = v end\n      end\n    end\n  end\n  if not (cfg.tower == \"AUTO\" or cfg.tower == \"NONE\" or A.TDIR[cfg.tower]) then\n    cfg.tower = A.SLOT_TOWER[cfg.tower] or \"AUTO\"\n  end\n  A.cfg = cfg\n  -- puddle countdown: {from, to (s after the tower cast), colour}; the last one is the tower soak\n  A.TW_STEP = {{0, 3.0, 0xFFFFFFFF}, {3.0, 5.55, 0xFFFFFFFF}, {5.55, 8.03, 0xFFFFFFFF}, {8.03, 10.97, 0xFF33FF33}}\n  function A.saveCfg()\n    if not FolderExists(A.CFG_DIR) then FolderCreate(A.CFG_DIR) end\n    local ok = pcall(FileSave, A.CFG_PATH, A.cfg)\n    A.cfgMsg = ok and \"Saved.\" or \"Save failed!\"\n  end\n  -- my slot from AnyoneCore's Party Roster (T1 T2 H1 H2 M1 M2 R1 R2), nil if the roster is not set\n  function A.slot()\n    local R = AnyoneCore and AnyoneCore.Roster\n    if not (R and R.mySlot) then return nil end\n    local ok, s = pcall(R.mySlot)\n    return ok and s or nil\n  end\n  -- role letter T/H/M/R from the roster slot, else from the job\n  A.JOBROLE = {[1]=\"T\",[3]=\"T\",[19]=\"T\",[21]=\"T\",[32]=\"T\",[37]=\"T\", [6]=\"H\",[24]=\"H\",[28]=\"H\",[33]=\"H\",[40]=\"H\",\n               [2]=\"M\",[4]=\"M\",[20]=\"M\",[22]=\"M\",[29]=\"M\",[30]=\"M\",[34]=\"M\",[39]=\"M\",[41]=\"M\",\n               [5]=\"R\",[7]=\"R\",[23]=\"R\",[25]=\"R\",[26]=\"R\",[27]=\"R\",[31]=\"R\",[35]=\"R\",[38]=\"R\",[42]=\"R\"}\n  function A.role()\n    local s = A.slot()\n    if s then return s:sub(1, 1) end\n    local p = TensorCore.mGetPlayer()\n    return p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Siegeflight + Wyvern's Rattle safety arrows (OnFrame). No text: line + arrow + circle to your spot.\n-- Frame of a dash: D = landing spot (opposite edge), u = from D back into the arena, v = west side.\n-- Light parties (HTMM / HTRR): LP1 = T1 H1 M1 M2 stacks next to the landing boss, LP2 = T2 H2 R1 R2 further out.\n--   RED  (Wyvern, 43902/45098): wait 5.5y off the middle line (yellow), step onto it once the 8y line went off\n--        (green): LP1 at 10y from D, LP2 at 24y from D.\n--   WHITE (Guardian, 43899/45097): sides, 10y off the line (green): LP1 west 10y from D, LP2 east 12y from D.\n--   Tanks + melee keep uptime at the boss's take-off end (4y in front, 5.5y to their side, yellow) until 6s\n--   before the stacks, then run to the stack spot.\n-- Rattle (43940): rows 40 wide x 8 deep walk away from the boss (2.5 / 5.0 / 7.6 / 10.2 / 12.7s). Bait both\n--   puddles 10.5y out (orange), then step 8y back behind the first row once it went off (green); stay until both\n--   puddle sets went off. Any other spot that is still in front of the wave is held just behind it (yellow).\nlocal M = A.m_siegeflight\nif not M then return end\nlocal now = Now()\nlocal GREEN, YELLOW, ORANGE = 0x33FF33, 0x00FFFF, 0x0099FF\nlocal slot = A.slot()\nlocal role = slot and slot:sub(1, 1) or A.role()\nlocal lp = slot and A.SLOT_LP[slot] or A.lp()\nif not lp then\n  if role == \"H\" then\n    local p = TensorCore.mGetPlayer()\n    local j = p and p.job\n    lp = (j == 24 or j == 33) and 1 or 2   -- pure healer (WHM/AST) = H1\n  else\n    lp = (role == \"T\" or role == \"M\") and 1 or 2\n  end\nend\nlocal close = (role == \"T\" or role == \"M\")\nlocal w = M.w\nlocal wEl = w and (now - w.t) / 1000 or 99\n-- rows of the wave that went off (cast events, with a time fallback)\nlocal rows = 0\nif wEl < 16 then\n  rows = w.n\n  local tk = wEl - 0.6\n  local nt = (tk > 12.72 and 5) or (tk > 10.17 and 4) or (tk > 7.59 and 3) or (tk > 4.97 and 2) or (tk > 2.52 and 1) or 0\n  if nt > rows then rows = nt end\nend\n-- 1) Wyvern's Rattle baits (owns the arrow for the first 7.2s)\nif wEl < 7.2 then\n  local L\n  if slot == \"T1\" then L = 1.5 elseif slot == \"T2\" then L = -1.5\n  elseif slot == \"M1\" then L = 3.5 elseif slot == \"M2\" then L = -3.5\n  elseif slot == \"H1\" then L = 5.0 elseif slot == \"H2\" then L = -5.0\n  elseif slot == \"R1\" then L = 6.5 elseif slot == \"R2\" then L = -6.5\n  else\n    local m = (role == \"T\" and 1.5) or (role == \"M\" and 3.5) or (role == \"H\" and 5.0) or 6.5\n    L = (lp == 1) and m or -m\n  end\n  local a, col = 2.5, GREEN\n  if rows < 1 then a, col = 10.5, ORANGE end\n  A.goTo(w.ox + a * w.fx + L * w.wx, w.oz + a * w.fz + L * w.wz, col, 1.0)\n  return\nend\n-- 2) Siegeflight\nlocal o = M.o\nif not o then return end\nlocal el = (now - o.t) / 1000\nif el > o.finAt + 0.6 or (o.finDone and now - o.finDone > 300) then return end\n-- The boss charge is narrow. Guardian's follow-up covers the wider center lane.\nlocal charge = el >= 0 and not o.midDone and el < o.dashAt\nlocal middle = not o.red and o.midDone and not o.finDone and el < o.finAt\nif charge or middle then\n  local red = TensorCore.getCachedDrawer(0x302222FF,0x302222FF,0x302222FF,0xCC2222FF,2)\n  local h = math.atan2(-o.ux,-o.uz)\n  local width = charge and 4 or 16\n  red:addRect(o.sx,0,o.sz,40,width,h,false,A.flags)\n  local dark = TensorCore.getStaticDrawer(0xF0101010,5)\n  local pale = TensorCore.getStaticDrawer(0xFFE8FFFF,2)\n  for side = -1, 1, 2 do\n    local x, z = side*width/2*o.vx, side*width/2*o.vz\n    dark:addLine(o.sx+x,0.06,o.sz+z,o.dx+x,0.06,o.dz+z,5)\n    pale:addLine(o.sx+x,0.08,o.sz+z,o.dx+x,0.08,o.dz+z,2)\n  end\nend\n-- Side hits resolve after the center line. The inner edges leave a four-yalm corridor.\nif o.red and o.midDone and not o.finDone and el < o.finAt then\n  local red = TensorCore.getCachedDrawer(0x302222FF,0x302222FF,0x302222FF,0xCC2222FF,2)\n  local h = math.atan2(-o.ux,-o.uz)\n  for side = -1, 1, 2 do\n    red:addRect(o.sx+side*11*o.vx,0,o.sz+side*11*o.vz,40,18,h,false,A.flags)\n    local x, z = A.CX + side*2*o.vx, A.CZ + side*2*o.vz\n    local x1, z1 = x - 20*o.ux, z - 20*o.uz\n    local x2, z2 = x + 20*o.ux, z + 20*o.uz\n    TensorCore.getStaticDrawer(0xF0101010,5):addLine(x1,0.06,z1,x2,0.06,z2,5)\n    TensorCore.getStaticDrawer(0xFFE8FFFF,2):addLine(x1,0.08,z1,x2,0.08,z2,2)\n  end\nend\nlocal tx, tz, col\n-- both stack markers in the same light party (a healer is dead): the non-healer target (or the later slot)\n-- takes its stack to the other light party's spot. Decided once per dash.\nif o.st2 and o.swap == nil then\n  o.swap = false\n  local p = TensorCore.mGetPlayer()\n  local me = p and p.id\n  local other = (me == o.st1 and o.st2) or (me == o.st2 and o.st1) or nil\n  local R = AnyoneCore and AnyoneCore.Roster\n  if slot and other and R and R.slotOf then\n    local ok, osl = pcall(R.slotOf, other)\n    if ok and type(osl) == \"string\" and A.SLOT_LP[osl] == lp then\n      local order = {T1 = 1, T2 = 2, H1 = 3, H2 = 4, M1 = 5, M2 = 6, R1 = 7, R2 = 8}\n      local oh, mh = osl:sub(1, 1) == \"H\", role == \"H\"\n      o.swap = (oh and not mh) or (oh == mh and (order[slot] or 0) > (order[osl] or 0))\n    end\n  end\nend\nif o.swap then lp = 3 - lp end\nlocal side = (lp == 1) and 1 or -1\nif close and el < o.finAt - 6.0 then\n  -- uptime at the take-off end, beside the dash line\n  tx = o.sx - 4 * o.ux + side * 5.5 * o.vx\n  tz = o.sz - 4 * o.uz + side * 5.5 * o.vz\n  col = YELLOW\nelseif o.red then\n  local a = (lp == 1) and 10 or 24\n  if o.midDone then\n    tx, tz, col = o.dx + a * o.ux, o.dz + a * o.uz, GREEN\n  else\n    tx = o.dx + a * o.ux + side * 5.5 * o.vx\n    tz = o.dz + a * o.uz + side * 5.5 * o.vz\n    col = YELLOW\n  end\nelse\n  local a = (lp == 1) and 10 or 12\n  tx = o.dx + a * o.ux + side * 10 * o.vx\n  tz = o.dz + a * o.uz + side * 10 * o.vz\n  col = GREEN\nend\n-- hold behind the Rattle wave while the target's row has not gone off yet\nif wEl < 16 and rows >= 1 and rows < 5 then\n  local ta = (tx - w.ox) * w.fx + (tz - w.oz) * w.fz\n  local front = 8 * rows\n  if ta > front - 0.5 and ta < 40.5 then\n    local d = ta - (front - 1.5)\n    tx, tz, col = tx - d * w.fx, tz - d * w.fz, YELLOW\n  end\nend\nif o.red and o.midDone and col == GREEN then\n  if not o.matthewCross and AnyoneCore and AnyoneCore.addTimedWorldTextOnEnt then\n    local player = TensorCore.mGetPlayer()\n    if player then\n      o.matthewCross = true\n      AnyoneCore.addTimedWorldTextOnEnt(1400, \"Cross now\", player.id, 0xFF33FF33, true, 1.35, 2)\n    end\n  end\nend\nA.goTo(tx, tz, col, 1.0)\n",
