							actionLua = "local e = eventArgs\nlocal now = Now()\nlocal ms = e.startTime + e.duration * 1000 - now\nlocal repeatIds = {[43889]=43895,[43890]=43896,[45077]=45079,[45078]=45080,\n                   [45083]=45091,[45084]=45092,[45086]=45094,[45087]=45095}\nlocal repeatId = repeatIds[e.aoeID]\nlocal state = data.matthewChainbladeBeams\nif repeatId and ms > 0 then\n    if not state or now-state.started > 1000 then\n        state={started=now,first={},predicted={}}\n        data.matthewChainbladeBeams=state\n    end\n    state.first[repeatId]={x=e.x,y=e.y,z=e.z,h=e.heading}\nelseif state and state.predicted[e.aoeID] then\n    Argus.deleteTimedShape(state.predicted[e.aoeID])\n    state.predicted[e.aoeID]=nil\nend\nif ms > 0 and ms < 8000 then\n    local drawer = TensorCore.getCachedDrawer(0x372222FF, 0x372222FF, 0x372222FF, 0xFF2222FF, 4)\n    drawer:addTimedRect(ms, e.x, e.y, e.z, 40, 4, e.heading, 0, false, true)\n    -- Only the repeat pair needs countdowns.\n    local id = e.aoeID\n    local repeatBeam = id == 43895 or id == 43896 or id == 45079 or id == 45080\n        or id == 45091 or id == 45092 or id == 45094 or id == 45095\n    if repeatBeam and AnyoneCore and AnyoneCore.addWorldTextCountdown then\n        local distance = 14\n        AnyoneCore.addWorldTextCountdown(ms, {\n            x = e.x + distance * math.sin(e.heading),\n            y = e.y + 2,\n            z = e.z + distance * math.cos(e.heading)\n        }, 0xFFAAAAFF, true, 1.35)\n    end\nend\nself.used = true",
