						{
							aType = "Lua",
							actionLua = "data.ark = data.ark or {}\nlocal A = data.ark\nif A.initV ~= 3 then\n  A.initV = 3\n  A.flags = Argus2.RenderFlags.FLAG_RENDER_OVERLAY\n  A.CX, A.CZ = 100, 100\n  -- same arrow as the Zelenia draws: line + arrow from you to the spot, circle on the spot\n  function A.goTo(x, z, col, rad)\n    local p = TensorCore.mGetPlayer()\n    if not (p and p.pos) then return end\n    local g = TensorCore.getCachedDrawer(0x55000000 + col, 0x88000000 + col, 0xFF000000 + col, 0xFF000000, 2)\n    local px, py, pz = p.pos.x, p.pos.y, p.pos.z\n    local d = TensorCore.getDistance2d2(px, py, pz, x, py, z)\n    if d > 0.8 then\n      TensorCore.getStaticDrawer(0xFF000000 + col, 3):addLine(px, py, pz, x, py, z, 3)\n      local tip = math.min(1.5, d * 0.35)\n      g:addArrow(px, py, pz, TensorCore.getHeadingToTarget2(px, py, pz, x, py, z), math.max(0.1, d - tip), 0.65, tip, 1.3, false, A.flags)\n    end\n    g:addCircle(x, py, z, rad or 1.0, false, A.flags)\n  end\n  -- outline ring (your own tower)\n  function A.ring(x, z, r, col)\n    local p = TensorCore.mGetPlayer()\n    local py = p and p.pos and p.pos.y or 0\n    TensorCore.getCachedDrawer(0x22000000 + col, 0x33000000 + col, 0x55000000 + col, 0xFF000000 + col, 3):addCircle(x, py, z, r, false, A.flags)\n  end\n  -- towers: 4 small (43920, r2, one per quadrant) + 2 big (43921, r4, one in the NW half, one in the SE half)\n  A.TOWER_KEYS  = {\"AUTO\", \"BIG_NW\", \"BIG_SE\", \"SM_NW\", \"SM_NE\", \"SM_SE\", \"SM_SW\", \"NONE\"}\n  -- names: tower, who takes it (role slots) and the closest waymark (A N, B E, C S, D W, 1 NW, 2 NE, 3 SE, 4 SW)\n  A.TOWER_NAMES = {\"Auto (Party Roster slot)\",\n                   \"Big tower NW - MT (between D and 1)\", \"Big tower SE - OT (between B and 3)\",\n                   \"Small tower NW - R1 (by 1)\", \"Small tower NE - R2 / H2 (by 2)\",\n                   \"Small tower SE - M2 (by 3)\", \"Small tower SW - M1 / H1 (by 4)\", \"No tower (flex)\"}\n  A.TDIR = {BIG_NW = {-1, -1, true}, BIG_SE = {1, 1, true}, SM_NW = {-1, -1, false}, SM_NE = {1, -1, false},\n            SM_SE = {1, 1, false}, SM_SW = {-1, 1, false}}\n  -- strat defaults: tanks NW/SE, R1 by 1 (NW), R2 by 2 (NE), M1 by 4 (SW), M2 by 3 (SE), H1 west -> SW, H2 east -> NE\n  A.SLOT_TOWER = {T1 = \"BIG_NW\", T2 = \"BIG_SE\", R1 = \"SM_NW\", R2 = \"SM_NE\", M1 = \"SM_SW\", M2 = \"SM_SE\", H1 = \"SM_SW\", H2 = \"SM_NE\"}\n  -- settings saved with FileSave / FileLoad in TensorReactions\\Settings\\Arkveld.settings.lua\n  -- (the old TensorReactions\\ArkveldEX_settings.lua is still read if the new file isn't there yet)\n  A.CFG_DIR = GetLuaModsPath() .. [[TensorReactions\\Settings\\]]\n  A.CFG_PATH = A.CFG_DIR .. [[Arkveld.settings.lua]]\n  local oldPath = GetLuaModsPath() .. [[TensorReactions\\ArkveldEX_settings.lua]]\n  local cfg = {tower = \"AUTO\", lcArrows = true, towerArrows = true, countdown = true}\n  local src = (FileExists(A.CFG_PATH) and A.CFG_PATH) or (FileExists(oldPath) and oldPath) or nil\n  if src then\n    local ok, saved = pcall(FileLoad, src)\n    if ok and type(saved) == \"table\" then\n      for k, v in pairs(saved) do\n        if cfg[k] ~= nil and type(v) == type(cfg[k]) then cfg[k] = v end\n      end\n    end\n  end\n  if not (cfg.tower == \"AUTO\" or cfg.tower == \"NONE\" or A.TDIR[cfg.tower]) then\n    cfg.tower = A.SLOT_TOWER[cfg.tower] or \"AUTO\"\n  end\n  A.cfg = cfg\n  -- puddle countdown: {from, to (s after the tower cast), colour}; the last one is the tower soak\n  A.TW_STEP = {{0, 3.0, 0xFFFFFFFF}, {3.0, 5.55, 0xFFFFFFFF}, {5.55, 8.03, 0xFFFFFFFF}, {8.03, 10.97, 0xFF33FF33}}\n  function A.saveCfg()\n    if not FolderExists(A.CFG_DIR) then FolderCreate(A.CFG_DIR) end\n    local ok = pcall(FileSave, A.CFG_PATH, A.cfg)\n    A.cfgMsg = ok and \"Saved.\" or \"Save failed!\"\n  end\n  -- my slot from AnyoneCore's Party Roster (T1 T2 H1 H2 M1 M2 R1 R2), nil if the roster is not set\n  function A.slot()\n    local R = AnyoneCore and AnyoneCore.Roster\n    if not (R and R.mySlot) then return nil end\n    local ok, s = pcall(R.mySlot)\n    return ok and s or nil\n  end\n  -- role letter T/H/M/R from the roster slot, else from the job\n  A.JOBROLE = {[1]=\"T\",[3]=\"T\",[19]=\"T\",[21]=\"T\",[32]=\"T\",[37]=\"T\", [6]=\"H\",[24]=\"H\",[28]=\"H\",[33]=\"H\",[40]=\"H\",\n               [2]=\"M\",[4]=\"M\",[20]=\"M\",[22]=\"M\",[29]=\"M\",[30]=\"M\",[34]=\"M\",[39]=\"M\",[41]=\"M\",\n               [5]=\"R\",[7]=\"R\",[23]=\"R\",[25]=\"R\",[26]=\"R\",[27]=\"R\",[31]=\"R\",[35]=\"R\",[38]=\"R\",[42]=\"R\"}\n  function A.role()\n    local s = A.slot()\n    if s then return s:sub(1, 1) end\n    local p = TensorCore.mGetPlayer()\n    return p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Steeltail Thrust + Chainblade Charge: safety arrows (role based, no text).\n-- 1) tail: line 6 wide BEHIND the boss -> T front, M flanks, H/R out at the front sides (green).\n-- 2) stack: everyone to the hitbox edge on the side of the marked player (marked player = pink),\n--    melee/tanks at 7.0y from the boss centre, healers/ranged at 8.5y (stack r6 covers both).\n-- 3) big puddle (r12 on the stack spot, 5s): to the far side of the boss; melee/tanks stay in\n--    melee range, healers/ranged further out and a bit to their side.\nlocal M = A.m_tail\nif not M then return end\nlocal now = Now()\nlocal tailOn = M.tT and now - M.tT < (M.tDur or 4600) + 800 and not (M.tDone and M.tDone >= M.tT)\nlocal stackOn = M.cT and now - M.cT < 10000 and not (M.hitT and M.hitT >= M.cT)\nlocal pudOn = M.hitT and M.cT and M.hitT >= M.cT and now - M.hitT < 5500\n  and not (M.pudDone and M.pudDone >= M.hitT)\n  and (M.cBig or (M.pudT and math.abs(M.pudT - M.hitT) < 2000))\nif not (tailOn or stackOn or pudOn) then return end\nlocal K = A.m_tailK\nif not (K and K.lbP) then\n  K = {\n    -- slot -> {angle from boss front (deg, + = boss left), distance from boss centre}\n    SPOT = {T1 = {0, 8.5}, T2 = {-20, 8.5}, M1 = {90, 8.5}, M2 = {-90, 8.5},\n            H1 = {60, 11}, H2 = {-60, 11}, R1 = {40, 14}, R2 = {-40, 14}},\n    ROLE = {T = {0, 8.5}, M = {90, 8.5}, H = {60, 11}, R = {40, 14}},\n    SIDE = {T1 = 1, T2 = -1, M1 = 1, M2 = -1, H1 = 1, H2 = -1, R1 = 1, R2 = -1},\n    lbP = {0, 0, 0, 0}, lbQ = {0, 0, 0, 0},\n  }\n  function K.go(x, z, col, rad)\n    local dx, dz = x - A.CX, z - A.CZ\n    local d = math.sqrt(dx * dx + dz * dz)\n    if d > 18.5 then x, z = A.CX + dx * 18.5 / d, A.CZ + dz * 18.5 / d end\n    A.goTo(x, z, col, rad)\n  end\n  A.m_tailK = K\nend\nlocal p = TensorCore.mGetPlayer()\nif not (p and p.pos) then return end\nlocal px, pz = p.pos.x, p.pos.z\nlocal bx, bz, bh = A.CX, A.CZ, nil\nlocal b = M.bossID and TensorCore.mGetEntity(M.bossID)\nif b and b.pos then bx, bz, bh = b.pos.x, b.pos.z, b.pos.h end\nlocal slot = A.slot()\nlocal role = A.role() or \"R\"\nlocal close = (role == \"T\" or role == \"M\")\n\nif pudOn then\n  local sx, sz = M.sx, M.sz\n  A.ring(sx, sz, 12, 0x3333FF)\n  local ux, uz = bx - sx, bz - sz\n  local dBS = math.sqrt(ux * ux + uz * uz)\n  local ox, oz, r\n  if dBS < 1 then\n    -- stack landed under the boss: run straight away from it\n    ux, uz = px - sx, pz - sz\n    local l = math.sqrt(ux * ux + uz * uz)\n    if l < 0.5 then ux, uz, l = 0, -1, 1 end\n    ux, uz = ux / l, uz / l\n    ox, oz, r = sx, sz, close and 14 or 15.5\n  else\n    ux, uz = ux / dBS, uz / dBS\n    ox, oz = bx, bz\n    r = close and math.max(7.0, 14.0 - dBS) or math.max(10.0, 15.5 - dBS)\n  end\n  local x, z = ox + ux * r, oz + uz * r\n  if not close then\n    -- healers / ranged fan out 20 deg to their side (left = H1/R1)\n    local side = slot and K.SIDE[slot] or 1\n    local c, s = 0.94, 0.342 * side\n    local x2, z2 = ox + r * (ux * c + uz * s), oz + r * (uz * c - ux * s)\n    local dx, dz = x2 - sx, z2 - sz\n    if dx * dx + dz * dz > 13.5 * 13.5 then x, z = x2, z2 end\n  end\n  K.go(x, z, 0x33FF33, 1.0)\n  return\nend\n\nif stackOn then\n  local me = (M.cTgt ~= nil and M.cTgt == p.id)\n  local tgt = me and p or (M.cTgt and TensorCore.mGetEntity(M.cTgt))\n  local r = close and 7.0 or 8.5\n  if tgt and tgt.pos then\n    if not M.cLock then\n      local dx, dz = tgt.pos.x - bx, tgt.pos.z - bz\n      local l = math.sqrt(dx * dx + dz * dz)\n      if l < 0.5 then\n        if bh then dx, dz = math.sin(bh), math.cos(bh) else dx, dz = 0, -1 end\n        l = 1\n      end\n      M.cdx, M.cdz, M.cLock = dx / l, dz / l, true\n    end\n    local x, z = bx + M.cdx * r, bz + M.cdz * r\n    if not me and now - M.cT > 5500 then\n      -- marked player stayed somewhere else: the stack lands on them, go to them\n      local tx, tz = tgt.pos.x, tgt.pos.z\n      local ex, ez = tx - (bx + M.cdx * 7.75), tz - (bz + M.cdz * 7.75)\n      if ex * ex + ez * ez > 16 then x, z = tx, tz end\n    end\n    K.go(x, z, me and 0xFF66FF or 0x33FF33, me and 1.0 or 1.5)\n  else\n    -- stack target not known yet: wait on the hitbox edge where you are\n    local dx, dz = px - bx, pz - bz\n    local l = math.sqrt(dx * dx + dz * dz)\n    if l < 0.5 then dx, dz, l = 0, -1, 1 end\n    K.go(bx + dx / l * r, bz + dz / l * r, 0x00FFFF, 1.0)\n  end\n  return\nend\n\n-- tail line: behind the boss, measured from the helper's heading (the boss turns to it)\nlocal h = M.tH or bh or 0\nlocal fx, fz = math.sin(h), math.cos(h)\nlocal lx, lz = math.cos(h), -math.sin(h)\nlocal sp = slot and K.SPOT[slot]\nlocal ang, dist\nif sp then\n  ang, dist = sp[1], sp[2]\nelse\n  local rr = K.ROLE[role] or K.ROLE.R\n  local lat = (px - bx) * lx + (pz - bz) * lz\n  ang, dist = rr[1] * (lat >= 0 and 1 or -1), rr[2]\nend\nlocal a = math.rad(ang)\nlocal c, s = math.cos(a), math.sin(a)\nlocal qa, qp = dist * c, dist * s\n-- clamp the spot into the arena first, then work in (along, perp) coordinates of the boss front\nlocal qx, qz = bx + fx * qa + lx * qp, bz + fz * qa + lz * qp\nlocal cdx, cdz = qx - A.CX, qz - A.CZ\nlocal cd = math.sqrt(cdx * cdx + cdz * cdz)\nif cd > 18.5 then\n  qx, qz = A.CX + cdx * 18.5 / cd, A.CZ + cdz * 18.5 / cd\n  qa, qp = (qx - bx) * fx + (qz - bz) * fz, (qx - bx) * lx + (qz - bz) * lz\nend\nlocal pa, pp = (px - bx) * fx + (pz - bz) * fz, (px - bx) * lx + (pz - bz) * lz\n-- never route through the line: if the straight walk enters {along < 0.5, |perp| < 4} step out sideways\n-- first (still in the line) or go round the flank 5y off the line (behind it), then to the spot\nlocal t0, t1, cross = 0, 1, true\nlocal d1, d2 = qa - pa, qp - pp\nlocal P = K.lbP\nP[1], P[2], P[3], P[4] = -d1, d1, -d2, d2\nlocal Q = K.lbQ\nQ[1], Q[2], Q[3], Q[4] = pa + 60, 0.5 - pa, pp + 4, 4 - pp\nfor i = 1, 4 do\n  local pi, qi = P[i], Q[i]\n  if pi == 0 then\n    if qi < 0 then cross = false break end\n  else\n    local t = qi / pi\n    if pi < 0 then\n      if t > t1 then cross = false break end\n      if t > t0 then t0 = t end\n    else\n      if t < t0 then cross = false break end\n      if t < t1 then t1 = t end\n    end\n  end\nend\nif cross then\n  local side\n  if math.abs(pp) > 0.3 then side = pp >= 0 and 1 or -1 else side = qp >= 0 and 1 or -1 end\n  local wa = math.abs(pp) < 4 and pa or 2.5\n  local wx, wz = bx + fx * wa + lx * side * 5, bz + fz * wa + lz * side * 5\n  local ex, ez = wx - px, wz - pz\n  if ex * ex + ez * ez > 1 then qx, qz = wx, wz end\nend\nK.go(qx, qz, 0x33FF33, 1.0)\n",
