		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "data.ark = data.ark or {}\nlocal A = data.ark\nif A.initV ~= 3 then\n  A.initV = 3\n  A.flags = Argus2.RenderFlags.FLAG_RENDER_OVERLAY\n  A.CX, A.CZ = 100, 100\n  -- same arrow as the Zelenia draws: line + arrow from you to the spot, circle on the spot\n  function A.goTo(x, z, col, rad)\n    local p = TensorCore.mGetPlayer()\n    if not (p and p.pos) then return end\n    local g = TensorCore.getCachedDrawer(0x55000000 + col, 0x88000000 + col, 0xFF000000 + col, 0xFF000000, 2)\n    local px, py, pz = p.pos.x, p.pos.y, p.pos.z\n    local d = TensorCore.getDistance2d2(px, py, pz, x, py, z)\n    if d > 0.8 then\n      TensorCore.getStaticDrawer(0xFF000000 + col, 3):addLine(px, py, pz, x, py, z, 3)\n      local tip = math.min(1.5, d * 0.35)\n      g:addArrow(px, py, pz, TensorCore.getHeadingToTarget2(px, py, pz, x, py, z), math.max(0.1, d - tip), 0.65, tip, 1.3, false, A.flags)\n    end\n    g:addCircle(x, py, z, rad or 1.0, false, A.flags)\n  end\n  -- outline ring (your own tower)\n  function A.ring(x, z, r, col)\n    local p = TensorCore.mGetPlayer()\n    local py = p and p.pos and p.pos.y or 0\n    TensorCore.getCachedDrawer(0x22000000 + col, 0x33000000 + col, 0x55000000 + col, 0xFF000000 + col, 3):addCircle(x, py, z, r, false, A.flags)\n  end\n  -- towers: 4 small (43920, r2, one per quadrant) + 2 big (43921, r4, one in the NW half, one in the SE half)\n  A.TOWER_KEYS  = {\"AUTO\", \"BIG_NW\", \"BIG_SE\", \"SM_NW\", \"SM_NE\", \"SM_SE\", \"SM_SW\", \"NONE\"}\n  -- names: tower, who takes it (role slots) and the closest waymark (A N, B E, C S, D W, 1 NW, 2 NE, 3 SE, 4 SW)\n  A.TOWER_NAMES = {\"Auto (Party Roster slot)\",\n                   \"Big tower NW - MT (between D and 1)\", \"Big tower SE - OT (between B and 3)\",\n                   \"Small tower NW - R1 (by 1)\", \"Small tower NE - R2 / H2 (by 2)\",\n                   \"Small tower SE - M2 (by 3)\", \"Small tower SW - M1 / H1 (by 4)\", \"No tower (flex)\"}\n  A.TDIR = {BIG_NW = {-1, -1, true}, BIG_SE = {1, 1, true}, SM_NW = {-1, -1, false}, SM_NE = {1, -1, false},\n            SM_SE = {1, 1, false}, SM_SW = {-1, 1, false}}\n  -- strat defaults: tanks NW/SE, R1 by 1 (NW), R2 by 2 (NE), M1 by 4 (SW), M2 by 3 (SE), H1 west -> SW, H2 east -> NE\n  A.SLOT_TOWER = {T1 = \"BIG_NW\", T2 = \"BIG_SE\", R1 = \"SM_NW\", R2 = \"SM_NE\", M1 = \"SM_SW\", M2 = \"SM_SE\", H1 = \"SM_SW\", H2 = \"SM_NE\"}\n  -- settings saved with FileSave / FileLoad in TensorReactions\\Settings\\Arkveld.settings.lua\n  -- (the old TensorReactions\\ArkveldEX_settings.lua is still read if the new file isn't there yet)\n  A.CFG_DIR = GetLuaModsPath() .. [[TensorReactions\\Settings\\]]\n  A.CFG_PATH = A.CFG_DIR .. [[Arkveld.settings.lua]]\n  local oldPath = GetLuaModsPath() .. [[TensorReactions\\ArkveldEX_settings.lua]]\n  local cfg = {tower = \"AUTO\", lcArrows = true, towerArrows = true, countdown = true}\n  local src = (FileExists(A.CFG_PATH) and A.CFG_PATH) or (FileExists(oldPath) and oldPath) or nil\n  if src then\n    local ok, saved = pcall(FileLoad, src)\n    if ok and type(saved) == \"table\" then\n      for k, v in pairs(saved) do\n        if cfg[k] ~= nil and type(v) == type(cfg[k]) then cfg[k] = v end\n      end\n    end\n  end\n  if not (cfg.tower == \"AUTO\" or cfg.tower == \"NONE\" or A.TDIR[cfg.tower]) then\n    cfg.tower = A.SLOT_TOWER[cfg.tower] or \"AUTO\"\n  end\n  A.cfg = cfg\n  -- puddle countdown: {from, to (s after the tower cast), colour}; the last one is the tower soak\n  A.TW_STEP = {{0, 3.0, 0xFFFFFFFF}, {3.0, 5.55, 0xFFFFFFFF}, {5.55, 8.03, 0xFFFFFFFF}, {8.03, 10.97, 0xFF33FF33}}\n  function A.saveCfg()\n    if not FolderExists(A.CFG_DIR) then FolderCreate(A.CFG_DIR) end\n    local ok = pcall(FileSave, A.CFG_PATH, A.cfg)\n    A.cfgMsg = ok and \"Saved.\" or \"Save failed!\"\n  end\n  -- my slot from AnyoneCore's Party Roster (T1 T2 H1 H2 M1 M2 R1 R2), nil if the roster is not set\n  function A.slot()\n    local R = AnyoneCore and AnyoneCore.Roster\n    if not (R and R.mySlot) then return nil end\n    local ok, s = pcall(R.mySlot)\n    return ok and s or nil\n  end\n  -- role letter T/H/M/R from the roster slot, else from the job\n  A.JOBROLE = {[1]=\"T\",[3]=\"T\",[19]=\"T\",[21]=\"T\",[32]=\"T\",[37]=\"T\", [6]=\"H\",[24]=\"H\",[28]=\"H\",[33]=\"H\",[40]=\"H\",\n               [2]=\"M\",[4]=\"M\",[20]=\"M\",[22]=\"M\",[29]=\"M\",[30]=\"M\",[34]=\"M\",[39]=\"M\",[41]=\"M\",\n               [5]=\"R\",[7]=\"R\",[23]=\"R\",[25]=\"R\",[26]=\"R\",[27]=\"R\",[31]=\"R\",[35]=\"R\",[38]=\"R\",[42]=\"R\"}\n  function A.role()\n    local s = A.slot()\n    if s then return s:sub(1, 1) end\n    local p = TensorCore.mGetPlayer()\n    return p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Exaflares / exalines / crystals / laser-3 spread: arrow (line + arrow + circle) to where YOU stand. No text.\n-- Role based: tanks + melee (\"close\") stay in melee range of the boss whenever the geometry allows,\n-- healers + ranged (\"far\") take the outer spot. Spots from the Party Roster slot, job role as fallback.\nlocal S = A.m_exa\nif not S then return end\nlocal GREEN, YELLOW = 0x33FF33, 0x00FFFF\n\n-- ---------- shared planner (time-expanded grid, 1y cells, 0.3s steps), defined once ----------\nif A.exaPV ~= 1 then\n  A.exaPV = 1\n  local G = {x = {}, z = {}, key = {}, nb = {}, nc = {}, n = 0}\n  for ix = -19, 19 do\n    for iz = -19, 19 do\n      if ix * ix + iz * iz <= 342.25 then\n        G.n = G.n + 1\n        G.x[G.n], G.z[G.n] = ix, iz\n        G.key[(ix + 20) * 41 + iz + 20] = G.n\n      end\n    end\n  end\n  for i = 1, G.n do\n    local l, c = {}, {}\n    for dx = -1, 1 do\n      for dz = -1, 1 do\n        local j = G.key[(G.x[i] + dx + 20) * 41 + G.z[i] + dz + 20]\n        if j then\n          l[#l + 1] = j\n          c[#c + 1] = (dx == 0 and dz == 0) and 0 or ((dx == 0 or dz == 0) and 0.01 or 0.014)\n        end\n      end\n    end\n    G.nb[i], G.nc[i] = l, c\n  end\n  A.exaG = G\n  function A.exaCell(x, z)\n    local dx, dz = x - A.CX, z - A.CZ\n    local r = math.sqrt(dx * dx + dz * dz)\n    if r > 18.4 then dx, dz = dx * 18 / r, dz * 18 / r end\n    return G.key[(math.floor(dx + 0.5) + 20) * 41 + math.floor(dz + 0.5) + 20]\n  end\n  -- dangers: {x, z, R, tau(ms), w(s)}; a cell is blocked from tau-w-dt to tau+w\n  function A.exaPlan(D, t0, dt, N, pc, term)\n    local P = {t0 = t0, dt = dt, N = N, pc = pc, uns = {}, V = {}, C = {}}\n    for k = 0, N do P.uns[k] = {} end\n    for _, d in ipairs(D) do\n      local ts = (d[4] - t0) / 1000\n      local k0 = math.max(0, math.ceil((ts - d[5] - dt) / dt))\n      local k1 = math.min(N, math.floor((ts + d[5]) / dt))\n      if k1 >= k0 then\n        local R, cx, cz = d[3], d[1] - A.CX, d[2] - A.CZ\n        for ix = math.max(-19, math.floor(cx - R)), math.min(19, math.ceil(cx + R)) do\n          for iz = math.max(-19, math.floor(cz - R)), math.min(19, math.ceil(cz + R)) do\n            local j = G.key[(ix + 20) * 41 + iz + 20]\n            if j and (ix - cx) ^ 2 + (iz - cz) ^ 2 < R * R then\n              for k = k0, k1 do P.uns[k][j] = true end\n            end\n          end\n        end\n      end\n    end\n    local v, u = {}, P.uns[N]\n    for i = 1, G.n do v[i] = u[i] and 1e9 or (term and term[i] or 0) end\n    P.V[N] = v\n    P.k = N - 1\n    return P\n  end\n  -- backward value iteration, a few layers per frame\n  function A.exaStep(P, layers)\n    local n, nb, nc, pc = G.n, G.nb, G.nc, P.pc\n    while layers > 0 and P.k >= 0 do\n      local k = P.k\n      local nv, u, u1, u2 = P.V[k + 1], P.uns[k], P.uns[k + 1], P.uns[k + 2]\n      local v, c = {}, {}\n      for i = 1, n do\n        v[i], c[i] = 1e9, i\n        if not u[i] then\n          local best, bj = 1e9, i\n          local l, lc = nb[i], nc[i]\n          for m = 1, #l do\n            local q = nv[l[m]] + lc[m]\n            if q < best then best, bj = q, l[m] end\n          end\n          if best < 1e9 then\n            local pen = 0\n            if u1 and u1[i] then pen = 0.5 end\n            if u2 and u2[i] then pen = pen + 0.2 end\n            v[i] = best + (pc and pc[i] or 0) + pen\n            c[i] = bj\n          end\n        end\n      end\n      P.V[k], P.C[k], P.k = v, c, k - 1\n      layers = layers - 1\n    end\n    P.done = P.k < 0\n    return P.done\n  end\n  -- where to go now: the furthest cell of your planned path you may already wait at; plus the next spot\n  function A.exaTarget(P, px, pz)\n    if not (P and P.done) then return nil end\n    local k = math.floor((Now() - P.t0) / 1000 / P.dt)\n    if k < 0 then k = 0 end\n    if k >= P.N then return nil end\n    local j = A.exaCell(px, pz)\n    if not j then return nil end\n    local V = P.V[k]\n    if V[j] >= 1e9 then\n      local best, bj = 26, nil\n      for i = 1, G.n do\n        if V[i] < 1e9 then\n          local d = (G.x[i] + A.CX - px) ^ 2 + (G.z[i] + A.CZ - pz) ^ 2\n          if d < best then best, bj = d, i end\n        end\n      end\n      if not bj then return nil end\n      return G.x[bj] + A.CX, G.z[bj] + A.CZ\n    end\n    local path = P.path or {}\n    P.path = path\n    path[0] = j\n    local M = 0\n    for m = 1, 8 do\n      if k + m - 1 >= P.N then break end\n      path[m] = P.C[k + m - 1][path[m - 1]]\n      M = m\n    end\n    local L = 0\n    for m = 1, M do\n      local cell, ok = path[m], true\n      for q = k, math.min(P.N, k + m) do\n        if P.uns[q][cell] then ok = false break end\n      end\n      if not ok then break end\n      L = m\n    end\n    local t, pv = path[L], path[M]\n    local tx, tz = G.x[t] + A.CX, G.z[t] + A.CZ\n    if pv ~= t then return tx, tz, G.x[pv] + A.CX, G.z[pv] + A.CZ end\n    return tx, tz\n  end\n  -- crystal explosion times: hit by an exaflare (<= 6 + hitbox) -> +1.65s; chain from another crystal -> +1.1s\n  function A.exaCrys(exa, cry)\n    local tt = {}\n    for i, c in ipairs(cry) do\n      local hb = c[3] and 1.2 or 0.7\n      for _, x in ipairs(exa) do\n        if (c[1] - x[1]) ^ 2 + (c[2] - x[2]) ^ 2 < (6 + hb) ^ 2 then\n          local t = x[3] + 1650\n          if not tt[i] or t < tt[i] then tt[i] = t end\n        end\n      end\n    end\n    for _ = 1, 8 do\n      local changed = false\n      for i, c in ipairs(cry) do\n        if tt[i] then\n          local r = c[3] and 12 or 6\n          for j, d in ipairs(cry) do\n            local hb = d[3] and 1.2 or 0.7\n            if j ~= i and (c[1] - d[1]) ^ 2 + (c[2] - d[2]) ^ 2 < (r + hb) ^ 2 and (not tt[j] or tt[i] + 1100 < tt[j] - 10) then\n              tt[j] = tt[i] + 1100\n              changed = true\n            end\n          end\n        end\n      end\n      if not changed then break end\n    end\n    return tt\n  end\n  -- 4 diagonal spots for wave 1/3 (+ exaflares), rotated clockwise to the cardinals for wave 2/4 (x exaflares)\n  A.EXA_DIAG = {NW = {-0.7071, -0.7071}, NE = {0.7071, -0.7071}, SE = {0.7071, 0.7071}, SW = {-0.7071, 0.7071}}\n  A.EXA_CARD = {NW = {0, -1}, NE = {1, 0}, SE = {0, 1}, SW = {-1, 0}}\n  A.EXA_SLOT = {T1 = \"NW\", T2 = \"NE\", M1 = \"SW\", M2 = \"SE\", R1 = \"NW\", R2 = \"NE\", H1 = \"SW\", H2 = \"SE\"}\n  -- laser-3 spread: {angle deg around the boss, distance}; 0 = straight into the arena, + = east when the boss is north\n  A.EXA_LSPOT = {T1 = {-60, 10}, M1 = {-20, 10}, M2 = {20, 10}, T2 = {60, 10},\n                 H1 = {-45, 17}, R1 = {-15, 17}, R2 = {15, 17}, H2 = {45, 17}}\nend\n\nlocal p = TensorCore.mGetPlayer()\nif not (p and p.pos) then return end\nlocal px, pz = p.pos.x, p.pos.z\nlocal now = Now()\nlocal close = A.close()\n\nlocal function bossXZ()\n  local b = A.boss()\n  if b and b.pos then return b.pos.x, b.pos.z end\n  return A.CX, A.CZ\nend\n-- per-cell role preference: close roles pay for every yard past melee range\nlocal function prefCost(bx, bz)\n  local G, pc = A.exaG, {}\n  for i = 1, G.n do\n    if close then\n      local d = math.sqrt((G.x[i] + A.CX - bx) ^ 2 + (G.z[i] + A.CZ - bz) ^ 2)\n      pc[i] = d > 10.5 and 0.02 * (d - 10.5) or 0\n    else\n      pc[i] = 0\n    end\n  end\n  return pc\nend\nlocal function crystalsFor(tStart)\n  local tw = S.tw\n  local cry = {}\n  if tw and tStart - tw.t > 9000 and tStart - tw.t < 45000 then\n    for _, c in ipairs(tw.list) do cry[#cry + 1] = c end\n  end\n  return cry\nend\nlocal function addCrystals(D, exa, cry)\n  local tt = A.exaCrys(exa, cry)\n  for i, c in ipairs(cry) do\n    -- +1.5 = 0.5 hitbox + 1.0 for cutting corners between 1y cells (replay: +1.0 let late followers clip small crystals)\n    if tt[i] then D[#D + 1] = {c[1], c[2], (c[3] and 12 or 6) + 1.5, tt[i] - 100, 0.45} end\n  end\nend\nlocal function draw(tx, tz, qx, qz)\n  if not tx then return end\n  A.goTo(tx, tz, GREEN, 0.7)\n  if qx and ((qx - tx) ^ 2 + (qz - tz) ^ 2) > 2.25 then A.ring(qx, qz, 0.7, YELLOW) end\nend\n\n-- ---------- 1) cross exaflares + crystals + 4/4 spreads (after towers 1) ----------\nlocal p1 = S.p1\nif p1 and now - p1.t0 < 31000 then\n  if not p1.dg then\n    local s = A.slot()\n    p1.dg = s and A.EXA_SLOT[s]\n    if not p1.dg then\n      local dx, dz = px - A.CX, pz - A.CZ\n      p1.dg = (dz < 0) and ((dx < 0) and \"NW\" or \"NE\") or ((dx < 0) and \"SW\" or \"SE\")\n    end\n    p1.cl = close\n  end\n  local r = p1.cl and 9.8 or 17.5\n  local dg, cd = A.EXA_DIAG[p1.dg], A.EXA_CARD[p1.dg]\n  local el = (now - p1.t0) / 1000\n  if el < 14.4 then\n    -- wave 1 (+), crystals and wave 2 (x): planned path, ends on your wave-3 diagonal spot\n    if not p1.plan and el > 0.1 then\n      local hs = p1.h\n      if #hs < 4 then\n        hs = {{94, 100, -1.5708}, {100, 106, 0}, {106, 100, 1.5708}, {100, 94, 3.1416}}\n      end\n      local exa, D = {}, {}\n      for _, h in ipairs(hs) do\n        local sx, sz = math.sin(h[3]), math.cos(h[3])\n        for i = 0, 2 do exa[#exa + 1] = {h[1] + 8 * i * sx, h[2] + 8 * i * sz, p1.t0 + 4900 + 1100 * i} end\n        local h2 = h[3] - math.pi / 4\n        local s2, c2 = math.sin(h2), math.cos(h2)\n        for i = 0, 2 do exa[#exa + 1] = {A.CX + (6 + 8 * i) * s2, A.CZ + (6 + 8 * i) * c2, p1.t0 + 11900 + 1100 * i} end\n      end\n      for _, x in ipairs(exa) do D[#D + 1] = {x[1], x[2], 7.0, x[3], 0.35} end\n      addCrystals(D, exa, crystalsFor(p1.t0))\n      local bx, bz = A.CX + r * dg[1], A.CZ + r * dg[2]\n      local term, G = {}, A.exaG\n      for i = 1, G.n do term[i] = math.sqrt((G.x[i] + A.CX - bx) ^ 2 + (G.z[i] + A.CZ - bz) ^ 2) end\n      p1.plan = A.exaPlan(D, p1.t0, 0.3, 48, prefCost(A.CX, A.CZ), term)\n    end\n    if p1.plan then\n      A.exaStep(p1.plan, 4)\n      local plan = p1.plan\n      local tx, tz, qx, qz = A.exaTarget(plan, px, pz)\n      if tx then\n        local k = math.max(0, math.floor((now - plan.t0) / (plan.dt * 1000)))\n        local here = A.exaCell(px, pz)\n        local blocked = false\n        local dx, dz = tx - px, tz - pz\n        local distance = math.sqrt(dx * dx + dz * dz)\n        -- Check the straight arrow at walking speed against the timed grid.\n        -- If this cell is about to be hit, keep the escape arrow available.\n        if distance > 1.25 and here and k + 1 <= plan.N\n            and not plan.uns[k][here] and not plan.uns[k + 1][here] then\n          local samples = math.ceil(distance * 2)\n          for i = 1, samples do\n            local fraction = i / samples\n            local cell = A.exaCell(px + fraction * dx, pz + fraction * dz)\n            local tick = math.min(plan.N, math.floor((now - plan.t0 + distance * fraction / 6 * 1000) / (plan.dt * 1000)))\n            tick = math.max(0, tick)\n            if cell and plan.uns[tick][cell] then blocked = true; break end\n          end\n        end\n        if blocked or p1.matthewCrossingBlocked then\n          if p1.matthewCrossingBlocked ~= blocked and AnyoneCore and AnyoneCore.addTimedWorldTextOnEnt then\n            AnyoneCore.addTimedWorldTextOnEnt(900, blocked and \"Wait\" or \"Move\",\n                p.id, blocked and 0xFF00FFFF or 0xFF33FF33, true, 1.35, 2)\n          end\n          p1.matthewCrossingBlocked = blocked\n        end\n        if blocked then\n          A.ring(px, pz, 0.7, YELLOW)\n        else\n          draw(tx, tz, qx, qz)\n        end\n      end\n    end\n  else\n    -- wave 3 (+): diagonal (spreads 1 here); wave 4 (x): cardinal (spreads 2). Inner and outer spots are 7.7y apart.\n    local w3 = p1.w[3] or (p1.t0 + 15100)\n    local w4 = p1.w[4] or (p1.t0 + 23100)\n    local sw = p1.cl and 6400 or 7500            -- inner leaves after the 14y hit (6.0-6.2s), outer after the 22y hit (7.1-7.25s)\n    if now - w4 < sw then\n      if now - w3 < sw then\n        draw(A.CX + r * dg[1], A.CZ + r * dg[2], A.CX + r * cd[1], A.CZ + r * cd[2])\n      else\n        draw(A.CX + r * cd[1], A.CZ + r * cd[2])\n      end\n    end\n  end\nend\n\n-- ---------- 2) Wrathful Rattle exalines (both axes, 4y wide lines, middle->edge->middle->edge) ----------\nlocal rt = S.rt\nif rt and now - rt.t0 < 38500 then\n  local el = (now - rt.t0) / 1000\n  -- line steps resolve at 6.1 8.8 11.3 14.0 16.5 18.8 21.3 23.9 26.6 29.2 31.8 34.4 37.1 (+0.6 fallback)\n  local E = A.EXA_RT or {6.1, 8.8, 11.3, 14.0, 16.5, 18.8, 21.3, 23.9, 26.6, 29.2, 31.8, 34.4, 37.1}\n  A.EXA_RT = E\n  local n = rt.n\n  for i = n + 1, #E do\n    if el > E[i] + 0.6 then n = i end\n  end\n  local cross = rt.cross or el > 3.9\n  -- Chainblade Blow is drawn by its own reaction: no arrows from its cast until its second hit\n  local pre = (not rt.cb) and el < 7.9\n  local post = (rt.cb and (rt.cbEnd or now - rt.cb > 10600)) or ((not rt.cb) and el > 18.4)\n  if pre or post then\n    local a, b\n    local bm, bs = 1, rt.bs\n    if pre then\n      local cl = rt.cl\n      if cl == nil then cl = close end\n      if not cl then bm = rt.fb or 1 end                          -- far: stay on your own half of the b axis\n      if not cross then\n        if cl then a, b = 5.5, 13.5 else a, b = 5.5, 5.5 end      -- out of the cross\n      else\n        if cl then a, b = 1.5, 13.5 else a, b = 1.5, 1.5 end      -- into the middle band as the lines go out\n      end\n    else\n      if not rt.s2 then\n        local dx, dz = px - A.CX, pz - A.CZ\n        local v = rt.zAx and dx or dz\n        rt.s2 = (v >= 0) and 1 or -1\n        -- where the Chainblade left you on the toward-boss axis: at b >= 14 you wait at 17.5 (behind the 14y line), else at 10\n        rt.hb = ((rt.zAx and dz or dx) * rt.bs >= 14) and 17.5 or 10\n      end\n      if n >= 12 and close then\n        -- the boss jumps to the other wall at step 12: follow it for uptime (lines are symmetric)\n        local bx, bz = bossXZ()\n        local v = rt.zAx and (bz - A.CZ) or (bx - A.CX)\n        if math.abs(v) > 12 then bs = (v > 0) and 1 or -1 end\n      end\n      if n < 6 then\n        if close then a, b = 1.5, rt.hb else a, b = 1.5, 1.5 end -- before the 14y line comes back in\n      elseif n < 8 then\n        if close then a, b = 1.5, 14 else a, b = 1.5, 1.5 end    -- step out over the 10y line once it fired\n      elseif n < 10 then\n        if close then a, b = 6, 14 else a, b = 6, 6 end          -- out of the centre band before it hits twice\n      elseif n < 12 then\n        a, b = 1.5, close and 14 or 1.5                          -- back in once the centre has hit twice\n      elseif n < 13 then\n        a, b = 1.5, close and 10 or 1.5                          -- in from the 14y band before it fires again\n      end\n    end\n    if a then\n      local s = (post and rt.s2) or rt.s\n      local x, z\n      if rt.zAx then\n        x, z = A.CX + s * a, A.CZ + bs * bm * b\n      else\n        x, z = A.CX + bs * bm * b, A.CZ + s * a\n      end\n      draw(x, z)\n    end\n  end\nend\n\n-- ---------- 3) edge exaflares from one side (after towers 3), with crystals ----------\nlocal ed = S.ed\nif ed and now - ed.t0 < 30000 and #ed.lanes > 0 then\n  if ed.dirty and now - ed.dirty > 100 then\n    ed.dirty = nil\n    local exa, D, last = {}, {}, 0\n    for _, l in ipairs(ed.lanes) do\n      for i = 0, 5 do\n        local t = l.t + 7980 + 1070 * i + l.off\n        exa[#exa + 1] = {l.x + 8 * i * l.dx, l.z + 8 * i * l.dz, t}\n        if t > last then last = t end\n      end\n    end\n    for _, x in ipairs(exa) do D[#D + 1] = {x[1], x[2], 7.0, x[3], 0.35} end\n    addCrystals(D, exa, crystalsFor(ed.t0))\n    for _, d in ipairs(D) do if d[4] > last then last = d[4] end end\n    local N = math.max(1, math.ceil((last + 400 - now) / 300))\n    ed.next = A.exaPlan(D, now, 0.3, N, prefCost(bossXZ()), nil)\n    ed.last = last\n  end\n  if ed.next then\n    if A.exaStep(ed.next, 4) then ed.plan, ed.next = ed.next, nil end\n  end\n  if ed.plan and ed.last and now < ed.last + 400 then\n    draw(A.exaTarget(ed.plan, px, pz))\n  end\nend\n\n-- ---------- 4) laser-3 spread (all alive get a 6y spread, boss at the wall), after the laser stopped ----------\n-- The laser leaves everyone on one side and only ~3.5 s remain, so the spots are not fixed per slot:\n-- a hex grid of points 7y apart (any two spots are spread-safe) is shared out by a global greedy match\n-- (cheapest player/point pair first) between the alive party members and the grid points.\n-- Cost = walking distance, plus for tanks/melee 0.6 per yard beyond 11y from the boss (melee uptime when it is cheap).\n-- Every client runs the same match on the same positions, so everyone gets a different point.\nlocal ls = S.ls\nif ls and ls.sp and now - ls.sp < 8300 then\n  local ready = (now - ls.sp > 4300) or (now - ls.sp > 2500 and ls.tick and now - ls.tick > 700)\n  if ready then\n    if not ls.pt then\n      local bx, bz = bossXZ()\n      if not A.EXA_HEX then\n        local H = {}\n        for j = -3, 3 do\n          for i = -4, 4 do\n            local x, z = 7 * (i + 0.5 * (j % 2)), 7 * 0.8660254 * j\n            if x * x + z * z <= 324 then H[#H + 1] = {A.CX + x, A.CZ + z} end\n          end\n        end\n        A.EXA_HEX = H\n      end\n      local H = A.EXA_HEX\n      local ok, party = pcall(TensorCore.entityList, \"myparty\")\n      local pl = {{px, pz, close, p.id or 0, true}}\n      if ok and type(party) == \"table\" then\n        for _, e in pairs(party) do\n          if e and e.pos and e.id ~= p.id and e.alive ~= false then\n            local r = A.JOBROLE[e.job]\n            pl[#pl + 1] = {e.pos.x, e.pos.z, r == \"T\" or r == \"M\", e.id or 0, false}\n          end\n        end\n      end\n      if #pl > 1 then\n        local takenP, takenH = {}, {}\n        for _ = 1, #pl do\n          local bc, bi, bj\n          for i, q in ipairs(pl) do\n            if not takenP[i] then\n              for j, h in ipairs(H) do\n                if not takenH[j] then\n                  local c = math.sqrt((q[1] - h[1]) ^ 2 + (q[2] - h[2]) ^ 2)\n                  if q[3] then\n                    local db = math.sqrt((h[1] - bx) ^ 2 + (h[2] - bz) ^ 2)\n                    if db > 11 then c = c + 0.6 * (db - 11) end\n                  end\n                  -- ties: lower entity id first, then lower point index (same on every client)\n                  if not bc or c < bc - 1e-6 or (math.abs(c - bc) <= 1e-6 and q[4] < pl[bi][4]) then bc, bi, bj = c, i, j end\n                end\n              end\n            end\n          end\n          if not bi then break end\n          takenP[bi], takenH[bj] = true, true\n          if pl[bi][5] then ls.pt = H[bj] break end\n        end\n      end\n      if not ls.pt then\n        -- no party list: fixed role spots around the boss (roster slot, else the nearer one of your role)\n        local ux, uz = A.CX - bx, A.CZ - bz\n        local ul = math.max(0.1, math.sqrt(ux * ux + uz * uz))\n        ux, uz = ux / ul, uz / ul\n        local function at(v)\n          local a = math.rad(v[1])\n          return {bx + v[2] * (math.sin(a) * uz + math.cos(a) * ux), bz + v[2] * (-math.sin(a) * ux + math.cos(a) * uz)}\n        end\n        local s = A.slot()\n        if s and A.EXA_LSPOT[s] then\n          ls.pt = at(A.EXA_LSPOT[s])\n        else\n          local bd\n          for _, v in pairs(A.EXA_LSPOT) do\n            if (v[2] == 10) == close then\n              local q = at(v)\n              local d = (q[1] - px) ^ 2 + (q[2] - pz) ^ 2\n              if not bd or d < bd then ls.pt, bd = q, d end\n            end\n          end\n        end\n      end\n    end\n    if ls.pt then draw(ls.pt[1], ls.pt[2]) end\n  end\nend\n",
							name = "Crystal exaflares | Timed route and crossing cue",
