						{
							aType = "Lua",
							actionLua = "local now = Now()\nif data.matthewVengeanceCrystals and now-data.matthewVengeanceCrystals < 13000 then self.used=true; return end\nlocal big, small = {}, {}\nfor _, e in pairs(TensorCore.entityList(\"contentid=14238\") or {}) do\n    local model = Argus.getEntityModel(e)\n    if e.pos and model == 18663 then big[#big+1]=e.pos\n    elseif e.pos and model == 18662 then small[#small+1]=e.pos end\nend\nif #big == 0 then self.used=true; return end\ndata.matthewVengeanceCrystals = now\nlocal function distance(a,b)\n    return (a.x-b.x)^2+(a.z-b.z)^2\nend\nlocal castFinish = eventArgs.channelTimeMax+0.3\nlocal function draw(q,r,delay)\n    local ms = math.floor((castFinish+delay)*1000)\n    TensorCore.getCachedDrawer(0x302222FF,0x302222FF,0x302222FF,0xCD2222FF,2)\n        :addTimedCircle(ms,q.x,q.y,q.z,r,0,false,true)\n    if AnyoneCore and AnyoneCore.addWorldTextCountdown then\n        AnyoneCore.addWorldTextCountdown(ms,{x=q.x,y=q.y+1,z=q.z},0xFFFFFFFF,true,1.25)\n    end\nend\nlocal times = {}\nfor _, q in ipairs(big) do\n    local delay = (q.x-100)^2+(q.z-100)^2 <= 121 and 1.6 or 2.7\n    draw(q,12,delay)\n    for _, s in ipairs(small) do\n        local d = distance(q,s)\n        if d <= 196 then\n            local predicted = delay + (d <= 144 and 0 or 1.2)\n            times[s]=math.min(times[s] or predicted,predicted)\n        end\n    end\nend\nfor q, delay in pairs(times) do draw(q,6,delay) end\nself.used=true",
