							actionLua = "local p = TensorCore.mGetPlayer()\nlocal now = Now()\nlocal seen = data.matthewQuietCues\nif not seen then seen = {}; data.matthewQuietCues = seen end\nlocal id = eventArgs.spellID\nif p and (not seen[id] or now - seen[id] > 1200) and AnyoneCore and AnyoneCore.addTimedWorldTextOnEnt then\n    seen[id] = now\n    AnyoneCore.addTimedWorldTextOnEnt(1600, \"Spread\", p.id, 0xFFFFFFFF, true, 1.35, 2.5)\nend\nself.used = true",
