							actionLua = "local e = eventArgs\nlocal L = data.ark and data.ark.lc\nif not L or Now() - L.t > 36000 then self.used = true; return end\nlocal previous = data.matthewLimitCleave\nif e.spellID == 43957 or e.spellID == 43960 then\n    if previous and previous.pull == L.t then previous.untilTime = nil end\n    self.used = true\n    return\nend\nif not (e.castPosX and e.castPosY and e.castPosZ) then self.used = true; return end\nif not (previous and previous.pull == L.t) then\n    local facing = data.matthewLimitFacing\n    previous = facing and math.abs(facing.at-L.t)<1000 and facing or {x=100-20*math.sin(L.h), z=100-20*math.cos(L.h)}\nend\nif previous then\n    local dx, dz = e.castPosX - previous.x, e.castPosZ - previous.z\n    if dx*dx + dz*dz > 1 then\n        local side = e.spellID == 43956 and 1 or -1\n        data.matthewLimitCleave = {\n            pull = L.t, x = e.castPosX, y = e.castPosY, z = e.castPosZ,\n            h = math.atan2(dx, dz) + side * math.pi/2,\n            untilTime = Now() + 2300\n        }\n    end\nend\nself.used = true",
