							actionLua = "local n = eventArgs.markerID - 403\nif n < 1 or n > 8 then self.used=true; return end\nlocal now = Now()\nlocal s = data.matthewLimitTargets\nif not s or now-s.at>1000 then\n    s={at=now,ids={}}\n    data.matthewLimitTargets=s\nend\ns.ids[n]=eventArgs.entityID\nself.used=true",
