nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- (shared by lz_chan.lua, lz_cast.lua and lz_mark.lua, pasted at their top) laser tracker start.\n-- s = +1 when the big crystal nearest the boss is east of the centre line (NS layout, big at (102,90)),\n-- -1 when it is west (WE layout, big at (88,96)). The laser-1 bait goes to that side, the group the other.\nif A.m_lasersV ~= 2 then\n  A.m_lasersV = 2\n  function A.m_lasersInit()\n    local side, bd\n    local list = A.ents(\"contentid=14238\")\n    if list then\n      for _, c in pairs(list) do\n        if c.modelid == 18663 and c.pos then\n          local d = (c.pos.x - 100) ^ 2 + (c.pos.z - 80) ^ 2\n          if not bd or d < bd then bd = d; side = (c.pos.x >= 100) and 1 or -1 end\n        end\n      end\n    end\n    -- fallback: big towers of the last tower set (crystals spawn on the towers)\n    if not side and A.tw and A.tw.list and A.tw.t and Now() - A.tw.t < 40000 then\n      for _, w in ipairs(A.tw.list) do\n        if w.big then\n          local d = (w.x - 100) ^ 2 + (w.z - 80) ^ 2\n          if not bd or d < bd then bd = d; side = (w.x >= 100) and 1 or -1 end\n        end\n      end\n    end\n    -- n: telegraphs seen; tel/h/hit: telegraph time, beam heading, first-hit time per laser;\n    -- mk: 470 markers seen, bait[k]: entity id of bait k, my[k]: I am bait k; c3/lastC: laser-3 hits; esc: my escape step\n    A.m_lasers = {t = Now(), s = side or 1, n = 0, tel = {0, 0, 0}, h = {}, hit = {}, c3 = 0, lastC = 0,\n                  mk = 0, lastMk = 0, bait = {}, my = {}, esc = {}}\n  end\nend\n\n-- Lasers: laser target marker 470 (one player per laser, 3 in order). Remember who has it and whether it is me.\nlocal e = eventArgs\nif not e then self.used = true return end\nif tonumber(e.markerID) == 470 then\n  -- marker #1 comes with (or up to 0.2 s before) the 43936 cast: start the tracker if it is not running\n  if not (A.m_lasers and Now() - A.m_lasers.t < 40000) then A.m_lasersInit() end\n  local S = A.m_lasers\n  if not (e.entityID == S.bait[S.mk] and Now() - S.lastMk < 1000) and S.mk < 3 then\n    S.mk = S.mk + 1; S.lastMk = Now(); S.bait[S.mk] = e.entityID\n    local p = TensorCore.mGetPlayer()\n    if p and e.entityID == p.id then S.my[S.mk] = true end\n  end\nend\nself.used = true",
