							actionLua = "data.ark = data.ark or {}\nlocal A = data.ark\nif A.initV ~= 3 then\n  A.initV = 3\n  A.flags = Argus2.RenderFlags.FLAG_RENDER_OVERLAY\n  A.CX, A.CZ = 100, 100\n  -- same arrow as the Zelenia draws: line + arrow from you to the spot, circle on the spot\n  function A.goTo(x, z, col, rad)\n    local p = TensorCore.mGetPlayer()\n    if not (p and p.pos) then return end\n    local g = TensorCore.getCachedDrawer(0x55000000 + col, 0x88000000 + col, 0xFF000000 + col, 0xFF000000, 2)\n    local px, py, pz = p.pos.x, p.pos.y, p.pos.z\n    local d = TensorCore.getDistance2d2(px, py, pz, x, py, z)\n    if d > 0.8 then\n      TensorCore.getStaticDrawer(0xFF000000 + col, 3):addLine(px, py, pz, x, py, z, 3)\n      local tip = math.min(1.5, d * 0.35)\n      g:addArrow(px, py, pz, TensorCore.getHeadingToTarget2(px, py, pz, x, py, z), math.max(0.1, d - tip), 0.65, tip, 1.3, false, A.flags)\n    end\n    g:addCircle(x, py, z, rad or 1.0, false, A.flags)\n  end\n  -- outline ring (your own tower)\n  function A.ring(x, z, r, col)\n    local p = TensorCore.mGetPlayer()\n    local py = p and p.pos and p.pos.y or 0\n    TensorCore.getCachedDrawer(0x22000000 + col, 0x33000000 + col, 0x55000000 + col, 0xFF000000 + col, 3):addCircle(x, py, z, r, false, A.flags)\n  end\n  -- towers: 4 small (43920, r2, one per quadrant) + 2 big (43921, r4, one in the NW half, one in the SE half)\n  A.TOWER_KEYS  = {\"AUTO\", \"BIG_NW\", \"BIG_SE\", \"SM_NW\", \"SM_NE\", \"SM_SE\", \"SM_SW\", \"NONE\"}\n  -- names: tower, who takes it (role slots) and the closest waymark (A N, B E, C S, D W, 1 NW, 2 NE, 3 SE, 4 SW)\n  A.TOWER_NAMES = {\"Auto (Party Roster slot)\",\n                   \"Big tower NW - MT (between D and 1)\", \"Big tower SE - OT (between B and 3)\",\n                   \"Small tower NW - R1 (by 1)\", \"Small tower NE - R2 / H2 (by 2)\",\n                   \"Small tower SE - M2 (by 3)\", \"Small tower SW - M1 / H1 (by 4)\", \"No tower (flex)\"}\n  A.TDIR = {BIG_NW = {-1, -1, true}, BIG_SE = {1, 1, true}, SM_NW = {-1, -1, false}, SM_NE = {1, -1, false},\n            SM_SE = {1, 1, false}, SM_SW = {-1, 1, false}}\n  -- strat defaults: tanks NW/SE, R1 by 1 (NW), R2 by 2 (NE), M1 by 4 (SW), M2 by 3 (SE), H1 west -> SW, H2 east -> NE\n  A.SLOT_TOWER = {T1 = \"BIG_NW\", T2 = \"BIG_SE\", R1 = \"SM_NW\", R2 = \"SM_NE\", M1 = \"SM_SW\", M2 = \"SM_SE\", H1 = \"SM_SW\", H2 = \"SM_NE\"}\n  -- settings saved with FileSave / FileLoad in TensorReactions\\Settings\\Arkveld.settings.lua\n  -- (the old TensorReactions\\ArkveldEX_settings.lua is still read if the new file isn't there yet)\n  A.CFG_DIR = GetLuaModsPath() .. [[TensorReactions\\Settings\\]]\n  A.CFG_PATH = A.CFG_DIR .. [[Arkveld.settings.lua]]\n  local oldPath = GetLuaModsPath() .. [[TensorReactions\\ArkveldEX_settings.lua]]\n  local cfg = {tower = \"AUTO\", lcArrows = true, towerArrows = true, countdown = true}\n  local src = (FileExists(A.CFG_PATH) and A.CFG_PATH) or (FileExists(oldPath) and oldPath) or nil\n  if src then\n    local ok, saved = pcall(FileLoad, src)\n    if ok and type(saved) == \"table\" then\n      for k, v in pairs(saved) do\n        if cfg[k] ~= nil and type(v) == type(cfg[k]) then cfg[k] = v end\n      end\n    end\n  end\n  if not (cfg.tower == \"AUTO\" or cfg.tower == \"NONE\" or A.TDIR[cfg.tower]) then\n    cfg.tower = A.SLOT_TOWER[cfg.tower] or \"AUTO\"\n  end\n  A.cfg = cfg\n  -- puddle countdown: {from, to (s after the tower cast), colour}; the last one is the tower soak\n  A.TW_STEP = {{0, 3.0, 0xFFFFFFFF}, {3.0, 5.55, 0xFFFFFFFF}, {5.55, 8.03, 0xFFFFFFFF}, {8.03, 10.97, 0xFF33FF33}}\n  function A.saveCfg()\n    if not FolderExists(A.CFG_DIR) then FolderCreate(A.CFG_DIR) end\n    local ok = pcall(FileSave, A.CFG_PATH, A.cfg)\n    A.cfgMsg = ok and \"Saved.\" or \"Save failed!\"\n  end\n  -- my slot from AnyoneCore's Party Roster (T1 T2 H1 H2 M1 M2 R1 R2), nil if the roster is not set\n  function A.slot()\n    local R = AnyoneCore and AnyoneCore.Roster\n    if not (R and R.mySlot) then return nil end\n    local ok, s = pcall(R.mySlot)\n    return ok and s or nil\n  end\n  -- role letter T/H/M/R from the roster slot, else from the job\n  A.JOBROLE = {[1]=\"T\",[3]=\"T\",[19]=\"T\",[21]=\"T\",[32]=\"T\",[37]=\"T\", [6]=\"H\",[24]=\"H\",[28]=\"H\",[33]=\"H\",[40]=\"H\",\n               [2]=\"M\",[4]=\"M\",[20]=\"M\",[22]=\"M\",[29]=\"M\",[30]=\"M\",[34]=\"M\",[39]=\"M\",[41]=\"M\",\n               [5]=\"R\",[7]=\"R\",[23]=\"R\",[25]=\"R\",[26]=\"R\",[27]=\"R\",[31]=\"R\",[35]=\"R\",[38]=\"R\",[42]=\"R\"}\n  function A.role()\n    local s = A.slot()\n    if s then return s:sub(1, 1) end\n    local p = TensorCore.mGetPlayer()\n    return p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Lasers (Wyvern's Weal): arrow to where you stand for each step. No text.\n-- Laid out for the big crystal east of the boss (s = +1, NS layout); every x is mirrored about 100 for s = -1.\n--  cast start -> 1st telegraph: laser-1 bait to the bait corner beside the big crystal (orange),\n--                               everyone else to the far corner next to the boss (tanks/melee in uptime).\n--  1st telegraph -> 2nd:        everyone (the bait too) in the far corner.\n--  2nd telegraph -> 3rd:        light-party stacks on the bait side: LP1 next to the boss, LP2 further out.\n--  3rd telegraph -> laser done: bait 3 in LP1 -> everyone back to the far corner.\n--                               bait 3 in LP2 -> the bait runs to the far corner alone, the rest go to / stay at LP1\n--                               (that beam starts on LP2 and sweeps away from LP1, so LP1 is never in it).\n--  laser done -> spreads go off: spread spots, tanks/melee in melee range.\n-- Movement rules on top of the spot:\n--  * the beam is a 60 x 6 rect from the boss centre (100,80): never cut across the front of the boss,\n--    go round via M (100,89.5) when the straight line passes within 7 of the boss centre;\n--  * from a telegraph until its first hit (1.6-2.1 s later): if I stand in that beam and my route does not\n--    get me out within 1.2 s, step out sideways first (toward my spot's side).\nlocal S = A.m_lasers\nif not S then return end\nlocal now = Now()\nlocal el = (now - S.t) / 1000\nif el < 0 or el > 41 then return end\nlocal p = TensorCore.mGetPlayer()\nif not (p and p.pos) then return end\nlocal n = S.n\nlocal r = A.role()\nif not r then return end\nlocal close = (r == \"T\" or r == \"M\")\nlocal frame = S.matthewFrame\nif not frame then\n    local boss = A.boss()\n    local q = boss and boss.pos\n    if q and (q.x-100)^2+(q.z-100)^2>225 then\n        local h = math.atan2(100-q.x,100-q.z)\n        frame={x=q.x,z=q.z,h=h,fx=math.sin(h),fz=math.cos(h)}\n        S.matthewFrame=frame\n    else\n        return\n    end\nend\nlocal s = S.s\nif S.h[1] then\n    local lateral = math.sin(S.h[1]-frame.h)\n    if math.abs(lateral)>0.15 then s=lateral>0 and 1 or -1 end\nend\nif n>=2 and S.h[2] then\n    local lateral = math.sin(S.h[2]-frame.h)\n    if math.abs(lateral)>0.15 then s=lateral>0 and -1 or 1 end\nend\nlocal col = 0x33FF33\nlocal x, z\nif not (A.m_lasersK and A.m_lasersK.v == 2) then\n  -- spots for s = +1\n  A.m_lasersK = {v = 2,\n    W_TM = {90.8, 83.3}, W_HR = {89.87, 83.45}, BAIT1 = {110.74, 84.63},\n    LP1 = {109.4, 83.4}, LP2 = {112.4, 92.4}, BAIT3W = {90.32, 83.52},\n    -- all go west first (bait 3 in LP1)\n    SPA = {T1 = {90.32, 83.52}, M1 = {94.54, 88.73}, M2 = {101.08, 90.24}, T2 = {107.16, 87.41},\n           H1 = {83.5, 92.5}, R1 = {87.5, 99.5}, R2 = {95.0, 104.5}, H2 = {103.5, 100.0}},\n    -- everyone but bait 3 east (bait 3 in LP2; bait 3 takes BAIT3W instead of its own spot)\n    SPB = {T1 = {109.68, 83.52}, M1 = {105.15, 88.92}, M2 = {98.21, 90.14}, H1 = {117.5, 93.5},\n           T2 = {91.5, 92.5}, H2 = {97.5, 97.5}, R1 = {104.0, 102.0}, R2 = {112.0, 101.0}},\n  }\nend\nlocal K = A.m_lasersK\nlocal lp = A.lp() or ((r == \"T\") and 1) or 2\nif n == 3 then\n  local t3 = (S.n >= 3) and (now - S.tel[3]) / 1000 or (el - 27.0)\n  if t3 > 13.2 then return end\n  -- which light party the 3rd beam starts on (from its heading)\n  local caseB = false\n  if S.h[3] then\n    local a1 = frame.h + math.atan2(s * (K.LP1[1] - 100), K.LP1[2] - 80)\n    local a2 = frame.h + math.atan2(s * (K.LP2[1] - 100), K.LP2[2] - 80)\n    local d1 = math.abs((S.h[3] - a1 + math.pi) % (2 * math.pi) - math.pi)\n    local d2 = math.abs((S.h[3] - a2 + math.pi) % (2 * math.pi) - math.pi)\n    caseB = d2 < d1\n  end\n  local iam3 = S.my[3]\n  local done = t3 > 8.6 or (S.c3 >= 8 and now - S.lastC > 50)\n  if done then return\n  elseif caseB and not iam3 then x, z = K.LP1[1], K.LP1[2]\n  elseif close then x, z = K.W_TM[1], K.W_TM[2]\n  else x, z = K.W_HR[1], K.W_HR[2] end\nelseif n == 2 then\n  if lp == 1 then x, z = K.LP1[1], K.LP1[2] else x, z = K.LP2[1], K.LP2[2] end\nelseif n == 1 then\n  if S.my[2] and S.hit[1] then x, z, col = K.W_HR[1], K.W_HR[2], 0x0099FF\n  elseif close then x, z = K.W_TM[1], K.W_TM[2] else x, z = K.W_HR[1], K.W_HR[2] end\nelse\n  if S.my[1] then\n    x, z, col = K.BAIT1[1], K.BAIT1[2], 0x0099FF\n  elseif close then x, z = K.W_TM[1], K.W_TM[2]\n  else x, z = K.W_HR[1], K.W_HR[2] end\nend\nlocal lateral,forward=s*(x-100),z-80\nx,z=frame.x+lateral*frame.fz+forward*frame.fx,frame.z-lateral*frame.fx+forward*frame.fz\nlocal px, pz = p.pos.x, p.pos.z\n-- route: the straight line to the spot must stay 7+ from the boss centre, else go via M\nlocal rx, rz = x, z\ndo\n  local dx, dz = x - px, z - pz\n  local L = dx * dx + dz * dz\n  if L > 1 then\n    local u = ((frame.x - px) * dx + (frame.z - pz) * dz) / L\n    if u < 0 then u = 0 elseif u > 1 then u = 1 end\n    local cx, cz = px + u * dx - frame.x, pz + u * dz - frame.z\n    if cx * cx + cz * cz < 49 then rx, rz = frame.x+9.5*frame.fx, frame.z+9.5*frame.fz end\n  end\nend\n-- escape step: from a telegraph until its first hit\nlocal k = S.n\nif k >= 1 and S.h[k] and not S.hit[k] and now - S.tel[k] < 2400 then\n  local h = S.h[k]\n  local ch, sh = math.cos(h), math.sin(h)\n  local e = S.esc[k]\n  if e == nil then\n    e = false\n    local ox, oz = px - frame.x, pz - frame.z\n    local pp, pj = ox * ch - oz * sh, ox * sh + oz * ch\n    local dx, dz = rx - px, rz - pz\n    local dl = math.sqrt(dx * dx + dz * dz)\n    local pr = (dl > 0.5) and (dx * ch - dz * sh) / dl or 0\n    local tl = 99\n    if pr > 0.05 then tl = (3.4 - pp) / (6 * pr) elseif pr < -0.05 then tl = (3.4 + pp) / (-6 * pr) end\n    if math.abs(pp) < 4.0 and pj > -1.0 and tl > 1.2 then\n      local dp = (x - frame.x) * ch - (z - frame.z) * sh\n      local need = ((dp >= 0) and 4.6 or -4.6) - pp\n      e = {px + need * ch, pz - need * sh}\n    end\n    S.esc[k] = e\n  end\n  if e and (px - e[1]) ^ 2 + (pz - e[2]) ^ 2 < 0.36 then e = false; S.esc[k] = false end\n  if e then rx, rz = e[1], e[2] end\nend\nA.goTo(rx, rz, col, 1.0)\n",
