							actionLua = "local e = eventArgs\nlocal now = Now()\nif e.spellID == 43937 then\n    local wave = {expires=now+8700, crystals={}}\n    data.matthewWealCrystals = wave\n    local crystals = TensorCore.entityList(\"contentid=14238\") or {}\n    for _, c in pairs(crystals) do\n        local model = Argus.getEntityModel(c)\n        if c.pos and (model == 18662 or model == 18663) then\n            local q = c.pos\n            wave.crystals[#wave.crystals+1] = {x=q.x,y=q.y,z=q.z,r=model==18663 and 12 or 6}\n        end\n    end\nelse\n    local wave = data.matthewWealCrystals\n    local c = TensorCore.mGetEntity(e.entityID)\n    if not (wave and c and c.pos) then self.used=true; return end\n    local q = c.pos\n    local entry\n    for _, a in ipairs(wave.crystals) do\n        if (a.x-q.x)^2+(a.z-q.z)^2 < 0.25 then entry=a; break end\n    end\n    if not entry then\n        entry={x=q.x,y=q.y,z=q.z,r=e.spellID==44810 and 12 or 6}\n        wave.crystals[#wave.crystals+1]=entry\n    end\n    local duration = (e.channelTimeMax+0.3)*1000\n    entry.hit = now+duration\n    wave.expires = math.max(wave.expires,entry.hit)\n    if AnyoneCore and AnyoneCore.addWorldTextCountdown then\n        AnyoneCore.addWorldTextCountdown(duration,{x=q.x,y=q.y+1,z=q.z},0xFFFFFFFF,true,1.25)\n    end\nend\nself.used=true",
