							actionLua = "local wave = data.matthewWealCrystals\nlocal now = Now()\nlocal p = TensorCore.mGetPlayer()\nif not (p and p.pos) then return end\nlocal preview = TensorCore.getCachedDrawer(0x00000000,0x00000000,0x00000000,0x802222FF,2)\nlocal danger = TensorCore.getCachedDrawer(0x252222FF,0x252222FF,0x252222FF,0xEE2222FF,3)\nfor _, a in ipairs(wave.crystals) do\n    if a.hit and a.hit > now then\n        danger:addCircle(a.x,a.y,a.z,a.r,false,Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n    elseif not a.hit and (p.pos.x-a.x)^2+(p.pos.z-a.z)^2 <= (a.r+7)^2 then\n        preview:addCircle(a.x,a.y,a.z,a.r,false,Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n    end\nend",
