						{
							aType = "Lua",
							actionLua = "local bait = data.matthewBeamBait\nlocal A = data.ark\nlocal origin = data.matthewWealCaster\nlocal actual = origin and math.abs(bait.at - origin.at) < 32000\n    and TensorCore.mGetEntity(origin.id)\nlocal boss = A and A.boss and A.boss()\nlocal holder = TensorCore.mGetEntity(bait.id)\nlocal source, target = boss and boss.pos, holder and holder.pos\nif not (source and target and holder.alive ~= false) then return end\nlocal dx, dz = target.x-source.x,target.z-source.z\nlocal length = math.sqrt(dx*dx+dz*dz)\nif length < 0.1 then return end\nlocal fx,fz = dx/length,dz/length\nlocal flags = Argus2.RenderFlags.FLAG_RENDER_OVERLAY\nlocal preview = TensorCore.getCachedDrawer(0x182222FF,0x182222FF,0x182222FF,0x992222FF,2)\nlocal beamSource = actual and actual.pos\nif beamSource then\n    local bx, bz = target.x-beamSource.x, target.z-beamSource.z\n    if bx*bx+bz*bz > 0.01 then\n        preview:addRect(beamSource.x,beamSource.y,beamSource.z,60,6,math.atan2(bx,bz),false,flags)\n    end\nend\nfor _, crystal in ipairs(bait.crystals or {}) do\n    local x,z = crystal.x-source.x,crystal.z-source.z\n    local along = x*fx+z*fz\n    if along >= 0 and along <= 60 and math.abs(x*fz-z*fx) <= 3+crystal.hitbox then\n        preview:addCircle(crystal.x,crystal.y,crystal.z,crystal.r,false,flags)\n    end\nend",
