							actionLua = "local e = eventArgs\nlocal now = Now()\nlocal current = data.matthewBeamBait\nif current and current.id == e.entityID and now - current.at < 1000 then self.used = true; return end\nif current and current.ring then Argus.deleteTimedShape(current.ring) end\nlocal first = not current or now - current.at > 15000\nlocal index = first and 1 or current.index+1\nlocal ms = index == 2 and 7800 or (index == 3 and 8400 or 8000)\nlocal p = TensorCore.mGetPlayer()\nlocal mine = p and p.id == e.entityID\nlocal ring = TensorCore.getCachedDrawer(0x20FF66AA,0x20FF66AA,0x20FF66AA,0xFFFF66AA,3)\n    :addTimedCircleOnEnt(ms+550,e.entityID,1.5,0,false,true)\ndata.matthewBeamBait = {id=e.entityID,at=now,index=index,mine=mine,ring=ring,previewAt=now+ms-3500}\nlocal bait = data.matthewBeamBait\nif index == 1 then\n    bait.crystals = {}\n    for _, crystal in pairs(TensorCore.entityList(\"contentid=14238\") or {}) do\n        local model = Argus.getEntityModel(crystal)\n        local q = crystal.pos\n        if q and (model == 18662 or model == 18663) then\n            local big = model == 18663\n            bait.crystals[#bait.crystals+1] = {x=q.x,y=q.y,z=q.z,r=big and 12 or 6,hitbox=big and 1.2 or 0.7}\n        end\n    end\nend\nif mine and AnyoneCore and AnyoneCore.addWorldTextCountdownOnEnt then\n    AnyoneCore.addWorldTextCountdownOnEnt(ms,e.entityID,0xFFFFFFFF,true,1.45,2.5)\nend\nself.used = true",
