							actionLua = "local b = data.matthewBeamBait\nif b and not b.released and Now() - b.at > 2000 and Now() - b.at < 10500 then\n    b.released = true\n    local caster = TensorCore.mGetEntity(eventArgs.entityID)\n    local q = caster and caster.pos\n    if q then\n        local ms = math.ceil((eventArgs.channelTimeMax + 0.3)*1000)\n        if ms > 0 then\n            TensorCore.getCachedDrawer(0x382222FF,0x382222FF,0x382222FF,0xE02222FF,3)\n                :addTimedRect(ms,q.x,q.y,q.z,60,6,q.h,0,false,true)\n        end\n    end\n    if b.ring then Argus.deleteTimedShape(b.ring); b.ring = nil end\n    if b.mine and AnyoneCore and AnyoneCore.Shotcall then AnyoneCore.Shotcall(\"Move\",true,1.5) end\nend\nself.used = true",
