							actionLua = "local e = eventArgs\nlocal caster = TensorCore.mGetEntity(e.entityID)\nlocal pos = caster and caster.pos\nif not pos or e.channelTimeMax <= 0 then self.used = true; return end\nlocal now = Now()\nlocal state = data.matthewArkExalines\nif not state or now >= state.expires then\n    state = {lanes = {}, shown = {}, expires = now + 42000}\n    data.matthewArkExalines = state\nend\nstate.nextCheck = now + 180\nlocal first = now + (e.channelTimeMax + 0.3) * 1000\nlocal middle = e.spellID == 43944\nlocal function add(x, z, dx, dz, count)\n    local stream = #state.lanes + 1\n    for i = 0, count - 1 do\n        state.lanes[#state.lanes + 1] = {\n            x = x + i * dx, y = pos.y, z = z + i * dz,\n            heading = pos.h, at = first + i * 2600, stream = stream, step = i,\n            middle = middle, width = 4, used = middle and i == 0\n        }\n    end\nend\nif middle then\n    -- One helper cast is one full opening beam. Its two half-width\n    -- lanes are retained only as anchors for the outward progression.\n    state.lanes[#state.lanes + 1] = {\n        x = pos.x, y = pos.y, z = pos.z, heading = pos.h,\n        at = first, width = 8\n    }\n    local x, z = math.cos(pos.h), -math.sin(pos.h)\n    add(pos.x + 2*x, pos.z + 2*z, 4*x, 4*z, 5)\n    add(pos.x - 2*x, pos.z - 2*z, -4*x, -4*z, 5)\nelse\n    local x, z = 100 - pos.x, 100 - pos.z\n    local length = math.sqrt(x*x + z*z)\n    if length > 1 then add(pos.x, pos.z, 4*x/length, 4*z/length, 10) end\nend\nself.used = true",
