							actionLua = "local state = data.matthewArkExalines\nlocal now = Now()\nlocal player = TensorCore.mGetPlayer()\nif not (player and player.incombat and player.pos) then\n    data.matthewArkExalines = nil\n    self.used = true\n    return\nend\nlocal pos = player.pos\nlocal first = math.huge\nfor _, lane in ipairs(state.lanes) do\n    if not lane.used and lane.at > now + 100 then first = math.min(first, lane.at) end\nend\nlocal wave = state.wave\nif not wave or (wave.pending == 0 and wave.ends <= now) then\n    if first > now + 4200 then\n        state.nextCheck = first - 4200\n        self.used = true\n        return\n    end\n    wave = {at = first, ends = first, pending = 0}\n    state.wave = wave\nend\nfor _, lane in ipairs(state.lanes) do\n    if not lane.used and lane.at > now + 100 and math.abs(lane.at - wave.at) <= 500 then\n        lane.used = true\n        lane.wave = wave\n        wave.pending = wave.pending + 1\n        wave.ends = math.max(wave.ends, lane.at)\n        local ms = math.ceil(lane.at - now)\n        TensorCore.getCachedDrawer(0x452222FF, 0x452222FF, 0x452222FF, 0xF52222FF, 3):addTimedCenteredRect(\n            ms, lane.x, lane.y, lane.z, 80, lane.width, lane.heading, 0, false, true)\n        if AnyoneCore and AnyoneCore.addWorldTextCountdown then\n            local fx, fz = math.sin(lane.heading), math.cos(lane.heading)\n            local along = math.max(-12, math.min(12, (pos.x - lane.x)*fx + (pos.z - lane.z)*fz))\n            AnyoneCore.addWorldTextCountdown(ms, {\n                x = lane.x + along*fx, y = lane.y + 1.5, z = lane.z + along*fz\n            }, 0xFFFFFFFF, true, 1.4)\n        end\n    end\nend\nstate.nextCheck = wave.pending == 0 and now or wave.ends\nself.used = true",
