						{
							aType = "Lua",
							actionLua = "local state = data.matthewArkExalines\nlocal e = eventArgs\nlocal caster = TensorCore.mGetEntity(e.entityID)\nlocal pos = caster and caster.pos\nif not pos then self.used = true; return end\nlocal now = Now()\nlocal function correct(hit)\n    hit.resolved = true\n    local wave = hit.wave\n    if wave then\n        wave.pending = wave.pending - 1\n        if wave.pending == 0 and wave == state.wave then\n            wave.ends = now\n            state.nextCheck = now\n        end\n    end\n    local delta = now - hit.at\n    hit.used = true\n    for _, lane in ipairs(state.lanes) do\n        if lane.stream == hit.stream and lane.step > hit.step and not lane.used then\n            lane.at = lane.at + delta\n        end\n    end\nend\nlocal function matches(lane)\n    return not lane.resolved and math.abs(lane.at - now) < 1300\n        and math.cos(lane.heading - e.heading) > 0.99\nend\nif e.spellID == 43944 then\n    for _, lane in ipairs(state.lanes) do\n        if lane.middle and lane.step == 0 and matches(lane)\n            and (lane.x-pos.x)^2 + (lane.z-pos.z)^2 < 9 then correct(lane) end\n    end\nelse\n    local best, score\n    for _, lane in ipairs(state.lanes) do\n        if matches(lane) then\n            local distance = (lane.x-pos.x)^2 + (lane.z-pos.z)^2\n            local rank = distance + math.abs(lane.at-now)/1300\n            if distance < 2.25 and (not score or rank < score) then best, score = lane, rank end\n        end\n    end\n    if best then correct(best) end\nend\nself.used = true",
