							actionLua = "local function violetCleave(ms,x,y,z,h,side)\n    local flags=Argus2.RenderFlags.FLAG_RENDER_OVERLAY\n    local fill=TensorCore.getCachedDrawer(0x16FFB6D6,0x16FFB6D6,0x16FFB6D6,0x16FFB6D6,1)\n    local shapes={fill:addTimedCenteredRect(ms,x,y,z,80,28,h,0,false,true,flags)}\n    local fx,fz=math.sin(h),math.cos(h)\n    local edgeX,edgeZ=x-side*14*fz,z+side*14*fx\n    local dx,dz=edgeX-100,edgeZ-100\n    local lateral=dx*fz-dz*fx\n    local chord=400-lateral*lateral\n    if chord>0 then\n        local along=dx*fx+dz*fz\n        local midX,midZ=edgeX-along*fx,edgeZ-along*fz\n        local length=2*math.sqrt(chord)\n        local dark=TensorCore.getCachedDrawer(0xE0201B25,0xE0201B25,0xE0201B25,0xE0201B25,1)\n        local violet=TensorCore.getCachedDrawer(0xFFFBD0E9,0xFFFBD0E9,0xFFFBD0E9,0xFFFBD0E9,1)\n        shapes[#shapes+1]=dark:addTimedCenteredRect(ms,midX,y+0.06,midZ,length,0.46,h,0,false,true,flags)\n        shapes[#shapes+1]=violet:addTimedCenteredRect(ms,midX,y+0.08,midZ,length,0.18,h,0,false,true,flags)\n    end\n    return shapes\nend\nlocal e = eventArgs\nlocal caster = TensorCore.mGetEntity(e.entityID)\nlocal pos = caster and caster.pos\nif not pos or e.channelTimeMax <= 0 then self.used = true; return end\nlocal id = e.spellID\nlocal first = id == 43891 or id == 43892 or id == 45085 or id == 45088\nlocal phase = first and \"first\" or \"repeat\"\nlocal draws = data.matthewVioletCleave or {}\ndata.matthewVioletCleave = draws\nfor _, shape in ipairs(draws[phase] or {}) do Argus.deleteTimedShape(shape) end\nlocal left = id == 43891 or id == 45085 or id == 43897 or id == 45093\nlocal offset = left and 7 or -7\nlocal forwardX, forwardZ = math.sin(pos.h), math.cos(pos.h)\nlocal x, z = pos.x + offset * forwardZ, pos.z - offset * forwardX\nif id == 43891 or id == 43892 or id == 45085 or id == 45088 then\n    data.matthewMirroredCleave = {\n        id=id, caster=e.entityID, expires=Now()+12000,\n        x=pos.x-offset*forwardZ, y=pos.y, z=pos.z+offset*forwardX, heading=pos.h\n    }\nend\nlocal ms = math.ceil((e.channelTimeMax + 0.3) * 1000)\ndraws[phase]=violetCleave(ms,x,pos.y,z,pos.h,left and 1 or -1)\nif AnyoneCore and AnyoneCore.addWorldTextCountdown then\n    AnyoneCore.addWorldTextCountdown(ms, {\n        x = x + 6 * forwardX, y = pos.y + 2, z = z + 6 * forwardZ\n    }, 0xFFFBD0E9, true, 1.45)\nend\nself.used = true",
