							actionLua = "local id = eventArgs.spellID\nlocal now = Now()\nlocal fast = id == 43897 or id == 43898 or id == 45093 or id == 45096\nlocal swap = data.matthewChainbladeSwap\nif fast and swap and now - swap < 3000 then self.used = true; return end\nlocal previous = data.matthewSideCall\nif not previous or previous.id ~= id or now - previous.at > 500 then\n    data.matthewSideCall = {id = id, at = now}\n    local leftHit = id == 43891 or id == 45085 or id == 43897 or id == 45093\n    if AnyoneCore and AnyoneCore.Shotcall then\n        AnyoneCore.Shotcall(leftHit and \"Boss right safe\" or \"Boss left safe\", true, 2)\n    end\nend\nself.used = true",
