							actionLua = "local e = eventArgs\nlocal caster = TensorCore.mGetEntity(e.entityID)\nlocal pos = caster and caster.pos\nif not pos or e.channelTimeMax <= 0 then self.used = true; return end\nlocal id = e.spellID\nif (id == 43897 or id == 43898 or id == 45093 or id == 45096) and data.matthewNextSide then\n    Argus.deleteTimedShape(data.matthewNextSide)\n    data.matthewNextSide = nil\nend\nlocal left = id == 43891 or id == 45085 or id == 43897 or id == 45093\nlocal offset = left and 7 or -7\nlocal forwardX, forwardZ = math.sin(pos.h), math.cos(pos.h)\nlocal x, z = pos.x + offset * forwardZ, pos.z - offset * forwardX\nif id == 43891 or id == 43892 or id == 45085 or id == 45088 then\n    data.matthewMirroredCleave = {\n        id=id, caster=e.entityID, expires=Now()+12000,\n        x=pos.x-offset*forwardZ, y=pos.y, z=pos.z+offset*forwardX, heading=pos.h\n    }\nend\nlocal ms = math.ceil((e.channelTimeMax + 0.3) * 1000)\nTensorCore.getCachedDrawer(0x412222FF, 0x412222FF, 0x412222FF, 0xFF2222FF, 5):addTimedCenteredRect(\n    ms, x, pos.y, z, 80, 28, pos.h, 0, false, true)\nif AnyoneCore and AnyoneCore.addWorldTextCountdown then\n    AnyoneCore.addWorldTextCountdown(ms, {\n        x = x + 6 * forwardX, y = pos.y + 2, z = z + 6 * forwardZ\n    }, 0xFFAAAAFF, true, 1.45)\nend\nself.used = true",
