					{
						data = 
						{
							aType = "Lua",
							actionLua = "local folder = GetLuaModsPath() .. [[TensorReactions\\Settings\\]]\nlocal path = folder .. \"ArkveldMatthew.settings.lua\"\nif not data.matthewOptions then\n    local saved = FileExists(path) and FileLoad(path)\n    data.matthewOptions = {rushCountdowns = type(saved) == \"table\" and saved.rushCountdowns == true}\nend\nlocal A = data.ark\nlocal M = A.m_rush\nlocal t = (Now()-M.t)/1000\nlocal flags = Argus2.RenderFlags.FLAG_RENDER_OVERLAY\nlocal red = TensorCore.getCachedDrawer(0x252222FF,0x252222FF,0x252222FF,0xDD2222FF,2)\nlocal preview = TensorCore.getCachedDrawer(0x142222FF,0x142222FF,0x142222FF,0x922222FF,2)\nlocal times = {5.86,7.97,10.06}\nlocal bands = {{0,8,7.5},{8,14,9.45},{14,20,11.45},{20,26,13.55}}\nlocal function countdown(key, remaining, x, z)\n    if not data.matthewOptions.rushCountdowns or not AnyoneCore or not AnyoneCore.addWorldTextCountdown then return end\n    M.matthewCountdowns = M.matthewCountdowns or {}\n    if M.matthewCountdowns[key] then return end\n    M.matthewCountdowns[key] = true\n    AnyoneCore.addWorldTextCountdown(math.floor(remaining*1000),{x=x,y=1.3,z=z},0xFFFFFFFF,true,1.2)\nend\nlocal quakeRed, quakePreview\nlocal x,z = M.dsx or M.sx,M.dsz or M.sz\nfor i, landing in ipairs(M.L) do\n    local remaining = times[i]-t\n    if x and z and remaining > 0 then\n        local dx,dz = landing.x-x,landing.z-z\n        countdown(i,remaining,(x+landing.x)/2,(z+landing.z)/2)\n        local drawer = remaining <= 3.5 and red or preview\n        drawer:addRect(x,0,z,math.sqrt(dx*dx+dz*dz),12,math.atan2(dx,dz),false,flags)\n    end\n    x,z=landing.x,landing.z\n    for _, band in ipairs(bands) do\n        local untilHit = landing.s+band[3]-t\n        if untilHit > 0 then\n            if not quakeRed then\n                A.matthewRushClipChannel = A.matthewRushClipChannel or Argus2.getNextUnusedChannel(true)\n                local clipChannel = A.matthewRushClipChannel\n                local maskFlags = Argus2.RenderFlags.FLAG_WARP_TERRAIN | Argus2.RenderFlags.FLAG_OCCLUDE\n                TensorCore.getStaticDrawer(0xFFFFFFFF,0,clipChannel,maskFlags):addDonut(100,0,100,20,60,false,maskFlags)\n                quakeRed = TensorCore.getCachedDrawer(0x252222FF,0x252222FF,0x252222FF,0xDD2222FF,2,clipChannel)\n                quakePreview = TensorCore.getCachedDrawer(0x142222FF,0x142222FF,0x142222FF,0x922222FF,2,clipChannel)\n            end\n            local drawer = untilHit <= 1.8 and quakeRed or quakePreview\n            local radius = (band[1]+band[2])/2\n            local player = TensorCore.mGetPlayer()\n            local pos = player and player.pos\n            if pos then\n                local dx,dz = pos.x-x,pos.z-z\n                local distance = math.sqrt(dx*dx+dz*dz)\n                if distance > 0.1 then\n                    countdown(i*100+band[2],untilHit,x+dx/distance*radius,z+dz/distance*radius)\n                end\n            end\n            if band[1]==0 then\n                drawer:addCircle(x,0,z,band[2],false,flags)\n            else\n                drawer:addDonut(x,0,z,band[1],band[2],false,flags)\n            end\n            break\n        end\n    end\nend",
