						{
							aType = "Lua",
							actionLua = "data.ark = data.ark or {}\nlocal A = data.ark\nif A.initV ~= 3 then\n  A.initV = 3\n  A.flags = Argus2.RenderFlags.FLAG_RENDER_OVERLAY\n  A.CX, A.CZ = 100, 100\n  -- same arrow as the Zelenia draws: line + arrow from you to the spot, circle on the spot\n  function A.goTo(x, z, col, rad)\n    local p = TensorCore.mGetPlayer()\n    if not (p and p.pos) then return end\n    local g = TensorCore.getCachedDrawer(0x55000000 + col, 0x88000000 + col, 0xFF000000 + col, 0xFF000000, 2)\n    local px, py, pz = p.pos.x, p.pos.y, p.pos.z\n    local d = TensorCore.getDistance2d2(px, py, pz, x, py, z)\n    if d > 0.8 then\n      TensorCore.getStaticDrawer(0xFF000000 + col, 3):addLine(px, py, pz, x, py, z, 3)\n      local tip = math.min(1.5, d * 0.35)\n      g:addArrow(px, py, pz, TensorCore.getHeadingToTarget2(px, py, pz, x, py, z), math.max(0.1, d - tip), 0.65, tip, 1.3, false, A.flags)\n    end\n    g:addCircle(x, py, z, rad or 1.0, false, A.flags)\n  end\n  -- outline ring (your own tower)\n  function A.ring(x, z, r, col)\n    local p = TensorCore.mGetPlayer()\n    local py = p and p.pos and p.pos.y or 0\n    TensorCore.getCachedDrawer(0x22000000 + col, 0x33000000 + col, 0x55000000 + col, 0xFF000000 + col, 3):addCircle(x, py, z, r, false, A.flags)\n  end\n  -- towers: 4 small (43920, r2, one per quadrant) + 2 big (43921, r4, one in the NW half, one in the SE half)\n  A.TOWER_KEYS  = {\"AUTO\", \"BIG_NW\", \"BIG_SE\", \"SM_NW\", \"SM_NE\", \"SM_SE\", \"SM_SW\", \"NONE\"}\n  -- names: tower, who takes it (role slots) and the closest waymark (A N, B E, C S, D W, 1 NW, 2 NE, 3 SE, 4 SW)\n  A.TOWER_NAMES = {\"Auto (Party Roster slot)\",\n                   \"Big tower NW - MT (between D and 1)\", \"Big tower SE - OT (between B and 3)\",\n                   \"Small tower NW - R1 (by 1)\", \"Small tower NE - R2 / H2 (by 2)\",\n                   \"Small tower SE - M2 (by 3)\", \"Small tower SW - M1 / H1 (by 4)\", \"No tower (flex)\"}\n  A.TDIR = {BIG_NW = {-1, -1, true}, BIG_SE = {1, 1, true}, SM_NW = {-1, -1, false}, SM_NE = {1, -1, false},\n            SM_SE = {1, 1, false}, SM_SW = {-1, 1, false}}\n  -- strat defaults: tanks NW/SE, R1 by 1 (NW), R2 by 2 (NE), M1 by 4 (SW), M2 by 3 (SE), H1 west -> SW, H2 east -> NE\n  A.SLOT_TOWER = {T1 = \"BIG_NW\", T2 = \"BIG_SE\", R1 = \"SM_NW\", R2 = \"SM_NE\", M1 = \"SM_SW\", M2 = \"SM_SE\", H1 = \"SM_SW\", H2 = \"SM_NE\"}\n  -- settings saved with FileSave / FileLoad in TensorReactions\\Settings\\Arkveld.settings.lua\n  -- (the old TensorReactions\\ArkveldEX_settings.lua is still read if the new file isn't there yet)\n  A.CFG_DIR = GetLuaModsPath() .. [[TensorReactions\\Settings\\]]\n  A.CFG_PATH = A.CFG_DIR .. [[Arkveld.settings.lua]]\n  local oldPath = GetLuaModsPath() .. [[TensorReactions\\ArkveldEX_settings.lua]]\n  local cfg = {tower = \"AUTO\", lcArrows = true, towerArrows = true, countdown = true}\n  local src = (FileExists(A.CFG_PATH) and A.CFG_PATH) or (FileExists(oldPath) and oldPath) or nil\n  if src then\n    local ok, saved = pcall(FileLoad, src)\n    if ok and type(saved) == \"table\" then\n      for k, v in pairs(saved) do\n        if cfg[k] ~= nil and type(v) == type(cfg[k]) then cfg[k] = v end\n      end\n    end\n  end\n  if not (cfg.tower == \"AUTO\" or cfg.tower == \"NONE\" or A.TDIR[cfg.tower]) then\n    cfg.tower = A.SLOT_TOWER[cfg.tower] or \"AUTO\"\n  end\n  A.cfg = cfg\n  -- puddle countdown: {from, to (s after the tower cast), colour}; the last one is the tower soak\n  A.TW_STEP = {{0, 3.0, 0xFFFFFFFF}, {3.0, 5.55, 0xFFFFFFFF}, {5.55, 8.03, 0xFFFFFFFF}, {8.03, 10.97, 0xFF33FF33}}\n  function A.saveCfg()\n    if not FolderExists(A.CFG_DIR) then FolderCreate(A.CFG_DIR) end\n    local ok = pcall(FileSave, A.CFG_PATH, A.cfg)\n    A.cfgMsg = ok and \"Saved.\" or \"Save failed!\"\n  end\n  -- my slot from AnyoneCore's Party Roster (T1 T2 H1 H2 M1 M2 R1 R2), nil if the roster is not set\n  function A.slot()\n    local R = AnyoneCore and AnyoneCore.Roster\n    if not (R and R.mySlot) then return nil end\n    local ok, s = pcall(R.mySlot)\n    return ok and s or nil\n  end\n  -- role letter T/H/M/R from the roster slot, else from the job\n  A.JOBROLE = {[1]=\"T\",[3]=\"T\",[19]=\"T\",[21]=\"T\",[32]=\"T\",[37]=\"T\", [6]=\"H\",[24]=\"H\",[28]=\"H\",[33]=\"H\",[40]=\"H\",\n               [2]=\"M\",[4]=\"M\",[20]=\"M\",[22]=\"M\",[29]=\"M\",[30]=\"M\",[34]=\"M\",[39]=\"M\",[41]=\"M\",\n               [5]=\"R\",[7]=\"R\",[23]=\"R\",[25]=\"R\",[26]=\"R\",[27]=\"R\",[31]=\"R\",[35]=\"R\",[38]=\"R\",[42]=\"R\"}\n  function A.role()\n    local s = A.slot()\n    if s then return s:sub(1, 1) end\n    local p = TensorCore.mGetPlayer()\n    return p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Rush (Devour): 3 dashes, then rings at each landing. Each landing has a helper channelling\n-- 43911 (circle r8, hits ~+7.5 s), 43912 (donut 8-14, +9.45), 43913 (14-20, +11.45), 43914 (20-26, +13.55).\n-- The 43911 channels for landings 1/2/3 come at s1, s1+~2.0, s1+~4.1. Dashes: start->L1 at s1+5.86,\n-- L1->L2 at +7.97, L2->L3 at +10.06 (12 wide). We work out:\n--   W  = wait spot just outside the 3rd circle, by the wall, safe from the dashes and the other rings (yellow)\n--   Fc = spot inside the 3rd circle for tanks/melee (as close to the boss as is safe)  (green)\n--   Ff = spot inside the 3rd circle for healers/ranged (back by the wall, most margin) (green)\nlocal e = eventArgs\nif not e then self.used = true return end\nif tonumber(e.spellID) ~= 43911 then self.used = true return end\nlocal en = TensorCore.mGetEntity(e.entityID)\nif not (en and en.pos) then self.used = true return end\nlocal now = Now()\nlocal M = A.m_rush\nif not M or now - M.t > 9000 or #M.L >= 3 then\n  M = {t = now, L = {}, id3 = nil, c3 = false, over = false}\n  local b = A.boss()\n  if b and b.pos then M.sx, M.sz = b.pos.x, b.pos.z end\n  A.m_rush = M\n  if AnyoneCore and AnyoneCore.Shotcall then\n    AnyoneCore.Shotcall(\"Stand near last charge\", true, 2)\n  end\nend\nlocal x, z = en.pos.x, en.pos.z\nfor _, l in ipairs(M.L) do\n  if math.abs(l.x - x) < 1 and math.abs(l.z - z) < 1 then self.used = true return end\nend\nM.L[#M.L + 1] = {x = x, z = z, s = (now - M.t) / 1000, id = e.entityID}\nif #M.L == 3 then M.id3 = e.entityID end\nif #M.L < 2 then self.used = true return end\n\n-- ---- solve -----------------------------------------------------------------\nlocal CX, CZ = A.CX, A.CZ\nlocal L1, L2, L3 = M.L[1], M.L[2], M.L[3]\nlocal l3x, l3z, s3\nif L3 then\n  l3x, l3z, s3 = L3.x, L3.z, L3.s\nelse\n  -- not placed yet: the three landings sit roughly evenly around the centre\n  l3x, l3z, s3 = 3 * CX - L1.x - L2.x, 3 * CZ - L1.z - L2.z, L2.s + 2.07\nend\nlocal sx, sz = M.sx, M.sz\nif not sx then\n  local ux, uz = l3x - CX, l3z - CZ\n  local d = math.max(0.1, math.sqrt(ux * ux + uz * uz))\n  sx, sz = CX + 20 * ux / d, CZ + 20 * uz / d\nend\nM.dsx, M.dsz = sx, sz   -- dash 1 start (frame.lua keeps you out of dash 1 on the way to the wait spot)\nlocal P = {{L1.x, L1.z, L1.s}, {L2.x, L2.z, L2.s}, {l3x, l3z, s3}}\nlocal RI, RO, RT = {0, 8, 14, 20}, {8, 14, 20, 26}, {7.5, 9.45, 11.45, 13.55}\n-- hazards: {t, kind(1 ring / 2 rect), a, b, c, d, landing, ring}\nlocal H = {}\nfor i = 1, 3 do\n  for k = 1, 4 do H[#H + 1] = {P[i][3] + RT[k], 1, P[i][1], P[i][2], RI[k], RO[k], i, k} end\nend\nlocal DT = {5.86, 7.97, 10.06}\nlocal fx, fz = sx, sz\nfor i = 1, 3 do\n  H[#H + 1] = {DT[i], 2, fx, fz, P[i][1], P[i][2], 0, 0}\n  fx, fz = P[i][1], P[i][2]\nend\nlocal tC = s3 + RT[1]\nlocal function hm(h, px, pz)\n  if h[2] == 1 then\n    local dx, dz = px - h[3], pz - h[4]\n    local d = math.sqrt(dx * dx + dz * dz)\n    return math.max(h[5] - d, d - h[6])\n  end\n  local ax, az = h[5] - h[3], h[6] - h[4]\n  local len = math.max(0.1, math.sqrt(ax * ax + az * az))\n  ax, az = ax / len, az / len\n  local vx, vz = px - h[3], pz - h[4]\n  local along = vx * ax + vz * az\n  local perp = math.abs(vx * az - vz * ax)\n  if along >= 0 and along <= len then return perp - 6 end\n  local ex = along < 0 and -along or along - len\n  if perp > 6 then return math.sqrt((perp - 6) ^ 2 + ex * ex) end\n  return ex\nend\n-- skip(h) true = hazard ignored for that spot\nlocal function margin(px, pz, t0, t1, skipL3donuts, skipL3circle)\n  local m = 99\n  for _, h in ipairs(H) do\n    if h[1] >= t0 and h[1] <= t1 and not (h[7] == 3 and ((h[8] > 1 and skipL3donuts) or (h[8] == 1 and skipL3circle))) then\n      local v = hm(h, px, pz)\n      if v < m then m = v end\n    end\n  end\n  return m\nend\nlocal ux, uz = l3x - CX, l3z - CZ\nlocal ud = math.max(0.1, math.sqrt(ux * ux + uz * uz))\nux, uz = ux / ud, uz / ud\nlocal function inArena(px, pz, r)\n  local dx, dz = px - CX, pz - CZ\n  return dx * dx + dz * dz <= r * r\nend\n-- F spots (after the 3rd circle went off): everything that still hits after it\nlocal bestC, bestF\nlocal tA = tC + 0.3\nfor di = 1, 14 do\n  local d = di * 0.5\n  for ai = -6, 6 do\n    local a = ai * 15 * math.pi / 180\n    local c, s = math.cos(a), math.sin(a)\n    local dx, dz = ux * c - uz * s, ux * s + uz * c\n    local px, pz = l3x + d * dx, l3z + d * dz\n    if inArena(px, pz, 19.3) then\n      local m = margin(px, pz, tA, 99, false, true)\n      -- close: nearest the boss with >= 1.2 margin; tie -> smallest angle\n      if m >= 1.2 and (not bestC or d < bestC[3] - 0.01 or (math.abs(d - bestC[3]) < 0.01 and math.abs(ai) < bestC[4])) then\n        bestC = {px, pz, d, math.abs(ai), m}\n      end\n      -- far: most margin (cap 3), tie -> further out by the wall, then smallest angle\n      local mc = math.min(m, 3)\n      if not bestF or mc > bestF[5] + 0.01 or (math.abs(mc - bestF[5]) <= 0.01 and (d > bestF[3] + 0.01 or (math.abs(d - bestF[3]) <= 0.01 and math.abs(ai) < bestF[4]))) then\n        bestF = {px, pz, d, math.abs(ai), mc}\n      end\n    end\n  end\nend\nif not bestC then bestC = bestF end\n-- W (before it): 9.5 from the 3rd landing, by the wall, safe from the dashes and the other rings until the\n-- 3rd circle; the way in (mid point W -> far spot) must be safe from what hits in the 2.1 s after it\n-- (this rules out the side where an earlier landing's big donut lands right after). tie -> nearest the far spot\nlocal bestW\nfor ai = 0, 71 do\n  local a = ai * 5 * math.pi / 180\n  local px, pz = l3x + 9.5 * math.sin(a), l3z + 9.5 * math.cos(a)\n  if inArena(px, pz, 19.0) then\n    local m = math.min(margin(px, pz, 4.5, tC + 0.5, true, true),\n                       margin((px + bestF[1]) / 2, (pz + bestF[2]) / 2, tC + 0.5, tC + 2.1, true, true), 2.5)\n    local dF = math.sqrt((px - bestF[1]) ^ 2 + (pz - bestF[2]) ^ 2)\n    if not bestW or m > bestW[3] + 0.01 or (math.abs(m - bestW[3]) <= 0.01 and dF < bestW[4]) then\n      bestW = {px, pz, m, dF}\n    end\n  end\nend\nM.W, M.Fc, M.Ff = bestW, bestC, bestF\nM.tC, M.tEnd, M.l3x, M.l3z, M.exact = tC, s3 + RT[4] + 0.1, l3x, l3z, (L3 ~= nil)\nself.used = true\n",
